        return Ok(app.to_string());
    }

    if let Some(app) = get_linked_app()? {
        return Ok(app);
    }

    InvalidArgumentSnafu {
        message: "App name is required. Use --app <org/app> or run 'spice cloud link' to link an app",
    }
    .fail()
}

