 74→/// Returns an error if authentication fails.
 75→pub async fn execute(ctx: &RuntimeContext, args: LoginArgs) -> Result<()> {
 76→    match args.command {
 77→        Some(LoginCommands::Dremio(provider_args)) => {
 78→            providers::login_dremio(ctx, provider_args).await
 79→        }
