107→/// Login to Spice.ai using OAuth flow or direct API key.
108→async fn login_spiceai(_ctx: &RuntimeContext, api_key: Option<String>) -> Result<()> {
109→    if let Some(key) = api_key {
110→        // Direct API key authentication
111→        merge_auth_config("SPICEAI", &[("API_KEY", key.as_str())])?;
112→        println!("\x1b[32mSuccessfully logged in to Spice.ai with API key\x1b[0m");
113→        return Ok(());
114→    }
115→
116→    // Spice.ai OAuth flow
117→    let base_url = get_spice_base_url();
118→    let auth_code = generate_auth_code();
119→
120→    let auth_url = format!("{base_url}/auth/token?code={auth_code}");
121→
122→    println!("Attempting to open Spice.ai authorization page in your default browser");
123→    println!("\nYour auth code:\n");
124→    println!("{}-{}", &auth_code[..4], &auth_code[4..]);
125→    println!("\nIf the browser does not open, visit the following URL manually:");
126→    println!("\n{auth_url}\n");
127→
128→    // Try to open browser automatically
129→    let _ = open::that(&auth_url);
130→
131→    tracing::info!("Waiting for authentication...");
132→
133→    // Poll for auth status
134→    let client = reqwest::Client::new();
135→    let exchange_url = format!("{base_url}/auth/token/exchange");
136→
137→    let access_token = loop {
138→        tokio::time::sleep(std::time::Duration::from_secs(1)).await;
139→
140→        let response = client
141→            .post(&exchange_url)
142→            .header("Content-Type", "application/json")
143→            .json(&serde_json::json!({ "code": auth_code }))
144→            .send()
145→            .await;
146→
147→        let response = match response {
148→            Ok(r) => r,
149→            Err(e) => {
150→                tracing::error!("Error exchanging auth code with spice.ai: {e}");
151→                continue;
152→            }
153→        };
154→
155→        let body: serde_json::Value = match response.json().await {
156→            Ok(v) => v,
157→            Err(e) => {
158→                tracing::error!("Error parsing exchange response: {e}");
159→                continue;
160→            }
161→        };
162→
163→        if body["access_denied"].as_bool().unwrap_or(false) {
164→            return Err(crate::error::Error::InvalidArgument {
165→                message: "Access denied".to_string(),
166→            });
167→        }
168→
169→        if let Some(token) = body["access_token"].as_str()
170→            && !token.is_empty()
171→        {
172→            break token.to_string();
173→        }
174→    };
175→
176→    // Try to read spicepod.yaml for preferred org/app
177→    let (org_name, app_name) = read_spicepod_metadata();
178→
179→    // Get auth context
180→    let auth_context = get_spice_auth_context(
181→        &base_url,
182→        &access_token,
183→        org_name.as_deref(),
184→        app_name.as_deref(),
185→    )
186→    .await?;
187→
188→    // Save credentials
189→    merge_auth_config(
190→        "SPICEAI",
191→        &[
192→            ("TOKEN", &access_token),
193→            ("API_KEY", &auth_context.app_api_key.unwrap_or_default()),
194→        ],
195→    )?;
196→
197→    println!(
198→        "\x1b[32mSuccessfully logged in to Spice.ai as {} ({})\x1b[0m",
199→        auth_context.username, auth_context.email
200→    );
201→    println!(
202→        "\x1b[32mUsing app {}/{}\x1b[0m",
203→        auth_context.org_name,
204→        auth_context.app_name.unwrap_or_default()
205→    );
206→
207→    Ok(())
208→}
209→
210→/// Get the Spice.ai base URL.
211→fn get_spice_base_url() -> String {
212→    if let Ok(url) = std::env::var("SPICE_BASE_URL") {
213→        return url;
214→    }
215→
216→    let version = env!("CARGO_PKG_VERSION");
217→    if version.ends_with("-dev") {
218→        "https://dev.spice.ai".to_string()
219→    } else {
220→        "https://spice.ai".to_string()
221→    }
222→}
223→
224→/// Generate a random 8-character auth code.
225→fn generate_auth_code() -> String {
226→    use rand::Rng;
227→    const CHARSET: &[u8] = b"REDACTED";
228→    let mut rng = rand::rng();
229→
230→    (0..8)
231→        .map(|_| {
232→            let idx = rng.random_range(0..CHARSET.len());
233→            CHARSET[idx] as char
234→        })
235→        .collect()
236→}
237→
238→/// Read org and app name from spicepod.yaml if it exists.
239→fn read_spicepod_metadata() -> (Option<String>, Option<String>) {
240→    let Ok(contents) = std::fs::read_to_string("spicepod.yaml") else {
241→        return (None, None);
242→    };
243→
244→    let Ok(yaml) = yaml::from_str::<yaml::Value>(&contents) else {
245→        return (None, None);
246→    };
247→
248→    let org_name = yaml
249→        .get("metadata")
250→        .and_then(|m| m.get("org"))
251→        .and_then(|o| o.as_str())
252→        .map(String::from);
253→
254→    let app_name = yaml.get("name").and_then(|n| n.as_str()).map(String::from);
255→
256→    (org_name, app_name)
257→}
258→
259→/// Auth context from Spice.ai API.
260→#[derive(Debug, serde::Deserialize)]
261→struct SpiceAuthContext {
262→    username: String,
263→    email: String,
264→    org_name: String,
265→    app_name: Option<String>,
266→    app_api_key: Option<String>,
267→}
268→
269→/// Get auth context from Spice.ai API.
270→async fn get_spice_auth_context(
271→    base_url: &str,
272→    access_token: &str,
273→    org_name: Option<&str>,
274→    app_name: Option<&str>,
275→) -> Result<SpiceAuthContext> {
276→    let mut url = format!("{base_url}/api/spice-cli/auth");
277→
278→    let mut params = Vec::new();
279→    if let Some(org) = org_name {
280→        params.push(format!("org_name={}", urlencoding::encode(org)));
281→    }
282→    if let Some(app) = app_name {
283→        params.push(format!("app_name={}", urlencoding::encode(app)));
284→    }
285→    if !params.is_empty() {
286→        url = format!("{url}?{}", params.join("&"));
287→    }
288→
289→    let client = reqwest::Client::new();
290→    let response = client
291→        .get(&url)
292→        .header("Authorization", format!("Bearer {access_token}"))
293→        .send()
294→        .await
295→        .map_err(|e| crate::error::Error::InvalidResponse {
296→            message: format!("Failed to get auth context: {e}"),
297→        })?;
298→
299→    if !response.status().is_success() {
300→        let text = response.text().await.unwrap_or_default();
301→        return Err(crate::error::Error::InvalidResponse {
302→            message: format!("Auth context request failed: {text}"),
303→        });
304→    }
305→
306→    // Parse the response - API returns nested org/app objects
307→    let body: serde_json::Value =
308→        response
309→            .json()
310→            .await
311→            .map_err(|e| crate::error::Error::InvalidResponse {
312→                message: format!("Failed to parse auth context: {e}"),
313→            })?;
314→
315→    Ok(SpiceAuthContext {
316→        username: body["username"].as_str().unwrap_or_default().to_string(),
317→        email: body["email"].as_str().unwrap_or_default().to_string(),
318→        org_name: body["org"]["name"].as_str().unwrap_or_default().to_string(),
319→        app_name: body["app"]["name"].as_str().map(String::from),
320→        app_api_key: body["app"]["api_key"].as_str().map(String::from),
321→    })
322→}
