 17→//! Authentication configuration management.
 18→//!
 19→//! Handles reading and writing credentials to .env or .env.local files.
 20→
 21→use crate::error::{ConfigIoSnafu, Result};
 22→use snafu::ResultExt;
 23→use std::collections::HashMap;
 24→use std::path::Path;
 25→
 26→/// Merge authentication configuration into the .env file.
 27→///
 28→/// Credentials are stored with the format: `SPICE_{AUTH_TYPE}_{PARAM}=value`
 29→///
 30→/// # Arguments
 31→///
 32→/// * `auth_type` - The authentication type (e.g., "DREMIO", "S3", "PG")
 33→/// * `params` - Key-value pairs of authentication parameters
 34→///
 35→/// # Errors
 36→///
 37→/// Returns an error if the .env file cannot be read or written.
 38→pub fn merge_auth_config(auth_type: &str, params: &[(&str, &str)]) -> Result<()> {
 39→    // Determine which env file to use
 40→    let env_file = if Path::new(".env.local").exists() {
 41→        ".env.local"
 42→    } else {
 43→        ".env"
 44→    };
 45→
 46→    // Read existing env vars (ignore errors - file might not exist)
 47→    let mut env_vars: HashMap<String, String> = if Path::new(env_file).exists() {
 48→        read_env_file(env_file).unwrap_or_default()
 49→    } else {
 50→        HashMap::new()
 51→    };
 52→
 53→    // Add new auth params
 54→    for (key, value) in params {
 55→        let secret_key = format!("SPICE_{auth_type}_{key}");
 56→        env_vars.insert(secret_key, (*value).to_string());
 57→    }
 58→
 59→    // Write back to file
 60→    write_env_file(env_file, &env_vars)?;
 61→
 62→    // Set file permissions to 0600 (owner read/write only)
 63→    #[cfg(unix)]
 64→    {
 65→        use std::os::unix::fs::PermissionsExt;
 66→        let permissions = std::fs::Permissions::from_mode(0o600);
 67→        std::fs::set_permissions(env_file, permissions).context(ConfigIoSnafu {
 68→            operation: "set permissions",
 69→            path: std::path::PathBuf::from(env_file),
 70→        })?;
 71→    }
 72→
 73→    Ok(())
 74→}
 75→
 76→/// Read environment variables from a .env file.
 77→fn read_env_file(path: &str) -> Result<HashMap<String, String>> {
 78→    let contents = std::fs::read_to_string(path).context(ConfigIoSnafu {
 79→        operation: "read",
 80→        path: std::path::PathBuf::from(path),
 81→    })?;
 82→
 83→    let mut vars = HashMap::new();
 84→    for line in contents.lines() {
 85→        let line = line.trim();
 86→        if line.is_empty() || line.starts_with('#') {
 87→            continue;
 88→        }
 89→
 90→        if let Some((key, value)) = line.split_once('=') {
 91→            let key = key.trim();
 92→            let value = value.trim();
 93→            // Remove surrounding quotes if present
 94→            let value = value
 95→                .strip_prefix('"')
 96→                .and_then(|v| v.strip_suffix('"'))
 97→                .unwrap_or(value);
 98→            let value = value
 99→                .strip_prefix('\'')
100→                .and_then(|v| v.strip_suffix('\''))
101→                .unwrap_or(value);
102→            vars.insert(key.to_string(), value.to_string());
103→        }
104→    }
105→
106→    Ok(vars)
107→}
108→
109→/// Write environment variables to a .env file.
110→fn write_env_file(path: &str, vars: &HashMap<String, String>) -> Result<()> {
111→    let mut lines: Vec<String> = vars
112→        .iter()
113→        .map(|(k, v)| {
114→            // Quote values that contain special characters
115→            if v.contains(' ') || v.contains('"') || v.contains('\'') || v.contains('=') {
116→                format!("{k}=\"{}\"", v.replace('"', "\\\""))
117→            } else {
118→                format!("{k}={v}")
119→            }
120→        })
121→        .collect();
122→
123→    // Sort for consistent output
124→    lines.sort();
125→
126→    let contents = lines.join("\n") + "\n";
127→    std::fs::write(path, contents).context(ConfigIoSnafu {
128→        operation: "write",
129→        path: std::path::PathBuf::from(path),
130→    })?;
131→
132→    Ok(())
133→}
