432→/// Perform Microsoft `OAuth2` device code flow authentication.
433→///
434→/// This is the CLI-friendly alternative to browser-based interactive auth.
435→/// The user is given a device code and URL to visit to complete authentication.
436→async fn msal_device_code_flow(
437→    tenant_id: &str,
438→    client_id: &str,
439→    scopes: &[&str],
440→) -> Result<String> {
441→    let authority_url = format!("https://login.microsoftonline.com/{tenant_id}");
442→    let device_code_url = format!("{authority_url}/oauth2/v2.0/devicecode");
443→    let token_url = format!("{authority_url}/oauth2/v2.0/token");
444→
445→    let scope_string = scopes.join(" ");
446→
447→    // Step 1: Request device code
448→    let client = reqwest::Client::new();
449→    let device_response = client
450→        .post(&device_code_url)
451→        .form(&[("client_id", client_id), ("scope", &scope_string)])
452→        .send()
453→        .await
454→        .map_err(|e| crate::error::Error::InvalidResponse {
455→            message: format!("Failed to request device code: {e}"),
456→        })?;
457→
458→    if !device_response.status().is_success() {
459→        let error_text = device_response.text().await.unwrap_or_default();
460→        return Err(crate::error::Error::InvalidResponse {
461→            message: format!("Device code request failed: {error_text}"),
462→        });
463→    }
464→
465→    let device_code_data: serde_json::Value =
466→        device_response
467→            .json()
468→            .await
469→            .map_err(|e| crate::error::Error::InvalidResponse {
470→                message: format!("Failed to parse device code response: {e}"),
471→            })?;
472→
473→    let device_code = device_code_data["device_code"].as_str().ok_or_else(|| {
474→        crate::error::Error::InvalidResponse {
475→            message: "No device_code in response".to_string(),
476→        }
477→    })?;
478→
479→    let user_code = device_code_data["user_code"].as_str().ok_or_else(|| {
480→        crate::error::Error::InvalidResponse {
481→            message: "No user_code in response".to_string(),
482→        }
483→    })?;
484→
485→    let verification_uri = device_code_data["verification_uri"]
486→        .as_str()
487→        .ok_or_else(|| crate::error::Error::InvalidResponse {
488→            message: "No verification_uri in response".to_string(),
489→        })?;
490→
491→    let interval = device_code_data["interval"].as_u64().unwrap_or(5);
492→    let expires_in = device_code_data["expires_in"].as_u64().unwrap_or(900);
493→
494→    // Step 2: Display instructions to user
495→    println!("\nTo sign in, use a web browser to open the page:");
496→    println!("  {verification_uri}");
497→    println!("\nAnd enter the code: {user_code}\n");
498→
499→    // Try to open browser automatically
500→    let _ = open::that(verification_uri);
501→
502→    println!("Waiting for authentication...");
503→
504→    // Step 3: Poll for token
505→    let start = std::time::Instant::now();
506→    let timeout = std::time::Duration::from_secs(expires_in);
507→    let poll_interval = std::time::Duration::from_secs(interval);
508→
509→    loop {
510→        if start.elapsed() > timeout {
511→            return Err(crate::error::Error::InvalidResponse {
512→                message: "Authentication timed out. Please try again.".to_string(),
513→            });
514→        }
515→
516→        tokio::time::sleep(poll_interval).await;
517→
518→        let token_response = client
519→            .post(&token_url)
520→            .form(&[
521→                ("grant_type", "urn:ietf:params:oauth:grant-type:device_code"),
522→                ("client_id", client_id),
523→                ("device_code", device_code),
524→            ])
525→            .send()
526→            .await
527→            .map_err(|e| crate::error::Error::InvalidResponse {
528→                message: format!("Token request failed: {e}"),
529→            })?;
530→
531→        let token_data: serde_json::Value =
532→            token_response
533→                .json()
534→                .await
535→                .map_err(|e| crate::error::Error::InvalidResponse {
536→                    message: format!("Failed to parse token response: {e}"),
537→                })?;
538→
539→        // Check for errors
540→        if let Some(error) = token_data["error"].as_str() {
541→            match error {
542→                "authorization_pending" => {
543→                    // User hasn't completed auth yet, keep polling
544→                    continue;
545→                }
546→                "slow_down" => {
547→                    // We need to slow down polling
548→                    tokio::time::sleep(std::time::Duration::from_secs(5)).await;
549→                    continue;
550→                }
551→                "expired_token" => {
552→                    return Err(crate::error::Error::InvalidResponse {
553→                        message: "Device code expired. Please try again.".to_string(),
554→                    });
555→                }
556→                "access_denied" => {
557→                    return Err(crate::error::Error::InvalidResponse {
558→                        message: "Access denied by user.".to_string(),
559→                    });
560→                }
561→                _ => {
562→                    let description = token_data["error_description"].as_str().unwrap_or(error);
563→                    return Err(crate::error::Error::InvalidResponse {
564→                        message: format!("Authentication error: {description}"),
565→                    });
566→                }
567→            }
568→        }
569→
570→        // Success - extract access token
571→        if let Some(access_token) = token_data["access_token"].as_str() {
572→            return Ok(access_token.to_string());
573→        }
574→
575→        return Err(crate::error::Error::InvalidResponse {
576→            message: "No access_token in token response".to_string(),
577→        });
578→    }
579→}
