 17→//! Cloud configuration for linking to Spice Cloud apps.
 18→
 19→use crate::error::{ConfigIoSnafu, CreateDirectorySnafu, Result};
 20→use serde::{Deserialize, Serialize};
 21→use snafu::ResultExt;
 22→use std::fs;
 23→use std::path::{Path, PathBuf};
 24→
 25→const CLOUD_CONFIG_DIR: &str = ".spice";
 26→const CLOUD_CONFIG_FILE: &str = "cloud.json";
 27→
 28→/// Cloud link configuration for a Spice Cloud app.
 29→#[derive(Debug, Clone, Serialize, Deserialize)]
 30→pub struct CloudLink {
 31→    pub org: String,
 32→    pub app: String,
 33→    #[serde(skip_serializing_if = "Option::is_none")]
 34→    pub app_id: Option<i64>,
 35→    #[serde(skip_serializing_if = "Option::is_none")]
 36→    pub region: Option<String>,
 37→    #[serde(skip_serializing_if = "Option::is_none")]
 38→    pub linked_at: Option<String>,
 39→}
 40→
 41→impl CloudLink {
 42→    /// Get the full app name in org/app format.
 43→    pub fn full_name(&self) -> String {
 44→        format!("{}/{}", self.org, self.app)
 45→    }
 46→}
 47→
 48→/// Get the path to the cloud config file.
 49→fn get_cloud_config_path() -> PathBuf {
 50→    Path::new(CLOUD_CONFIG_DIR).join(CLOUD_CONFIG_FILE)
 51→}
 52→
 53→/// Load the cloud link configuration from the current directory.
 54→pub fn load_cloud_link() -> Result<Option<CloudLink>> {
 55→    let config_path = get_cloud_config_path();
 56→
 57→    if !config_path.exists() {
 58→        return Ok(None);
 59→    }
 60→
 61→    let content = fs::read_to_string(&config_path).context(ConfigIoSnafu {
 62→        operation: "read",
 63→        path: config_path,
 64→    })?;
 65→
 66→    let link: CloudLink =
 67→        serde_json::from_str(&content).map_err(|e| crate::error::Error::ConfigParse {
 68→            message: format!("Failed to parse cloud config: {e}"),
 69→        })?;
 70→
 71→    Ok(Some(link))
 72→}
 73→
 74→/// Save the cloud link configuration to the current directory.
 75→pub fn save_cloud_link(link: &CloudLink) -> Result<()> {
 76→    let config_dir = Path::new(CLOUD_CONFIG_DIR);
 77→    fs::create_dir_all(config_dir).context(CreateDirectorySnafu { path: config_dir })?;
 78→
 79→    let config_path = get_cloud_config_path();
 80→    let content =
 81→        serde_json::to_string_pretty(link).map_err(|e| crate::error::Error::ConfigParse {
 82→            message: format!("Failed to serialize cloud config: {e}"),
 83→        })?;
 84→
 85→    fs::write(&config_path, content).context(ConfigIoSnafu {
 86→        operation: "write",
 87→        path: config_path,
 88→    })?;
 89→
 90→    Ok(())
 91→}
 92→
 93→/// Remove the cloud link configuration from the current directory.
 94→pub fn remove_cloud_link() -> Result<()> {
 95→    let config_path = get_cloud_config_path();
 96→
 97→    if config_path.exists() {
 98→        fs::remove_file(&config_path).context(ConfigIoSnafu {
 99→            operation: "delete",
100→            path: config_path,
101→        })?;
102→    }
103→
104→    // Try to remove the .spice directory if it's empty
105→    let config_dir = Path::new(CLOUD_CONFIG_DIR);
106→    if config_dir.exists() {
107→        let _ = fs::remove_dir(config_dir);
108→    }
109→
110→    Ok(())
111→}
112→
113→/// Get the linked app name if available.
114→pub fn get_linked_app() -> Result<Option<String>> {
115→    let link = load_cloud_link()?;
116→    Ok(link.map(|l| l.full_name()))
117→}
