    if let Ok(url) = std::env::var("SPICE_BASE_URL") {
        return url;
    }

    let version = env!("CARGO_PKG_VERSION");
    if version.ends_with("-dev") {
        "https://dev.spice.ai".to_string()
    } else {
        "https://spice.ai".to_string()
    }
}

