import { redirectWithCookies } from '@/lib/auth';
import {
  upsertContact,
  updateContact,
  PROPERTY_USER_ID,
  PROPERTY_GITHUB_USERNAME,
} from '@/lib/hubspot';
import { setupUserOrg } from '@/lib/orgs';
import { createDbUser, getLoggedInDbUser } from '@/lib/users';
import { sendEvent } from '@/utils/ga';
import { getSessionId } from '@/utils/gaCookies';
import { getSupabaseUser } from '@/utils/supabase/get-user';
import { createClient } from '@/utils/supabase/server';
import { track } from '@vercel/analytics/server';
import { after, NextResponse } from 'next/server';
import { logServerEvent, getAnonymousStableId } from '@/lib/statsig/server';
import { AnalyticsEvents } from '@/lib/statsig/events';

/**
 * Fetches GitHub user profile to get account creation date.
 * Used for traffic quality analysis - users who created GitHub account
 * on the same day as Spice signup are likely not developers.
 */
async function getGitHubAccountCreatedAt(
  accessToken: string,
): Promise<{ accountAgeDays: number | null }> {
  try {
    const response = await fetch('https://api.github.com/user', {
      headers: {
        Authorization: `Bearer ${accessToken}`,
        Accept: 'application/vnd.github.v3+json',
        'User-Agent': 'Spice-Cloud-Portal',
      },
    });

    if (!response.ok) {
      console.error(
        '[auth/callback] GitHub API error:',
        response.status,
        response.statusText,
      );
      return { accountAgeDays: null };
    }

    const userData = await response.json();
    const createdAt = userData.created_at as string | undefined;

    if (createdAt) {
      const createdDate = new Date(createdAt);
      const now = new Date();
      const accountAgeDays = Math.floor(
        (now.getTime() - createdDate.getTime()) / (1000 * 60 * 60 * 24),
      );
      return { accountAgeDays };
    }

    return { accountAgeDays: null };
  } catch (error) {
    console.error('[auth/callback] Failed to fetch GitHub profile:', error);
    return { accountAgeDays: null };
  }
}

export const dynamic = 'force-dynamic';
export const maxDuration = 30;

export async function GET(request: Request) {
  const sessionId = await getSessionId();
  const requestUrl = new URL(request.url);
  const code = requestUrl.searchParams.get('code');
  const redirectTo = requestUrl.searchParams.get('redirectTo');

  if (code) {
    const supabase = await createClient();
    const { data, error } = await supabase.auth.exchangeCodeForSession(code);
    if (error) {
      console.error('[auth/callback] error:', error);
      return NextResponse.redirect(requestUrl.origin + '/login?error=auth');
    }

    if (data?.session) {
      const metadata = data.session.user.user_metadata;
      const username = (metadata['user_name'] as string).toLowerCase();

      const origin =
        process.env['NODE_ENV'] === 'development' && !!process.env['BASE_URL']
          ? process.env['BASE_URL']
          : requestUrl.origin;

      // PERFORMANCE OPTIMIZATION: Parallel queries for better performance
      // Get auth user, db user, and org check all in parallel
      const [
        { data: personalOrg },
        {
          data: { user: authUser },
        },
      ] = await Promise.all([
        supabase
          .from('orgs')
          .select('id')
          .eq('name_lowercase', username)
          .maybeSingle(),
        getSupabaseUser(supabase),
      ]);

      // Try to get existing user, create if not exists
      let user = authUser
        ? await getLoggedInDbUser(supabase, authUser)
        : undefined;

      if (!user && authUser) {
        user = await createDbUser(authUser);
      }

      if (!user) {
        console.error(
          '[auth/callback]',
          'failed to get or create user',
          authUser,
        );
        return NextResponse.redirect(
          requestUrl.origin + '/login?error=user_creation',
        );
      }

      // PERFORMANCE OPTIMIZATION: Move all non-critical operations to background
      // This includes HubSpot sync, GA tracking, and analytics
      after(async () => {
        try {
          const fullName =
            authUser?.user_metadata['fullName'] ||
            authUser?.user_metadata['name'] ||
            authUser?.user_metadata['user_name'];

          const [firstname, lastname] = fullName?.split(' ') || ['', ''];

          // Parallel execution of HubSpot and GA operations
          const operations: Promise<any>[] = [];

          // HubSpot contact management
          if (user.email) {
            if (!user.hubspot_contact_id) {
              // New user - create HubSpot contact
              operations.push(
                upsertContact(user.id, user.email, {
                  firstname,
                  lastname,
                  [PROPERTY_GITHUB_USERNAME]: user.username,
                }).then(async (contact) => {
                  if (contact) {
                    await supabase
                      .from('users')
                      .update({ hubspot_contact_id: contact.id })
                      .eq('id', user.id);
                  }
                }),
              );
            } else {
              // Existing user - sync HubSpot contact
              operations.push(
                updateContact(user.hubspot_contact_id, {
                  email: user.email,
                  firstname,
                  lastname,
                  [PROPERTY_GITHUB_USERNAME]: user.username,
                  [PROPERTY_USER_ID]: String(user.id),
                }),
              );
            }
          }

          // Google Analytics login event
          if (user.ga_client_id) {
            operations.push(
              sendEvent(user.ga_client_id, {
                user_id: String(user.id),
                events: [
                  {
                    name: 'login',
                    params: {
                      session_id: sessionId,
                      engagement_time_msec: 5000,
                      method: 'GitHub',
                    },
                  },
                ],
              }),
            );
          }

          // Execute all background operations in parallel
          await Promise.allSettled(operations);
        } catch (error) {
          console.error('[auth/callback] background task error:', error);
        }
      });

      // if no personal org exists, create one
      if (!personalOrg) {
        console.log(`[auth/callback] setting up ${username}`);

        // Get Statsig stable ID for funnel tracking
        // This connects anonymous landing page visitors to authenticated users
        const stableID = await getAnonymousStableId();

        // PERFORMANCE: Track signup start, but don't await
        track('signup', {
          state: 'start',
          username: username,
        });

        const { org } = await setupUserOrg(supabase, user);

        if (org) {
          // PERFORMANCE: Track signup success, but don't await
          track('signup', {
            state: 'success',
            username: username,
          });

          after(async () => {
            // Fetch GitHub account creation date for traffic quality analysis
            // Users who created GitHub account same day as signup are likely not developers
            const { accountAgeDays: githubAccountAgeDays } =
              await getGitHubAccountCreatedAt(data.session.provider_token!);

            // Track user signup and onboarding started in Statsig
            // Include stableID to enable funnel analysis across
            // landing page (anonymous) -> portal (authenticated)
            // Include GitHub account age for traffic quality segmentation
            await logServerEvent(
              {
                userID: String(user.id),
                ...(stableID && { stableID }),
                custom: { account_id: String(org.id), username: user.username },
              },
              AnalyticsEvents.USER_SIGNED_UP,
              {
                org_name: org.name,
                auth_provider: 'github',
                ...(githubAccountAgeDays !== null
                  ? {
                      github_account_age_days: githubAccountAgeDays,
                    }
                  : {}),
              },
            );
          });
        }

        const targetUrl = redirectTo
          ? origin + redirectTo
          : origin + `/${org.name}/onboard`;

        return redirectWithCookies(
          targetUrl,
          data.session.provider_token!,
          data.session.provider_refresh_token!,
          sessionId,
        );
      }

      // Handle existing user redirects
      const targetUrl = redirectTo
        ? origin + redirectTo
        : origin + `/${username}`;

      return redirectWithCookies(
        targetUrl,
        data.session.provider_token!,
        data.session.provider_refresh_token!,
        sessionId,
      );
    }
  }

  return NextResponse.redirect(requestUrl.origin);
}

import { NextResponse } from 'next/server';
import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from '@scp/db';
import { withTokenAuth } from '@/utils/tokenAuth';

/**
 * @swagger
 * /api/spice-cli/auth:
 *   get:
 *     summary: Get Spice CLI authentication info
 *     description: Returns user, org, and app info for CLI authentication, including API key.
 *     parameters:
 *       - in: query
 *         name: org_name
 *         required: false
 *         schema:
 *           type: string
 *         description: Organization name to filter
 *       - in: query
 *         name: app_name
 *         required: false
 *         schema:
 *           type: string
 *         description: App name to filter
 *     responses:
 *       200:
 *         description: Auth info for CLI
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 id:
 *                   type: integer
 *                 email:
 *                   type: string
 *                 username:
 *                   type: string
 *                 org:
 *                   type: object
 *                   properties:
 *                     id:
 *                       type: integer
 *                     name:
 *                       type: string
 *                 app:
 *                   type: object
 *                   properties:
 *                     id:
 *                       type: integer
 *                     name:
 *                       type: string
 *                     api_key:
 *                       type: string
 *       404:
 *         description: User, org, or app not found
 *     tags:
 *       - Spice CLI
 */
export const GET = withTokenAuth(async (req, { supabase, authUser, orgId }) => {
  const { searchParams } = new URL(req.url);
  const org_name = searchParams.get('org_name');
  const app_name = searchParams.get('app_name');

  const { data: user } = await supabase
    .from('users')
    .select('id, email, username')
    .is('deleted_at', null)
    .eq('auth_id', authUser.id)
    .maybeSingle();

  if (!user) {
    console.error(
      '[api/device]',
      `User for auth.user ${authUser.id} not found`,
    );
    return NextResponse.json({}, { status: 404 });
  }

  // get either specified org or personal org
  let org = await (orgId
    ? getOrgById(supabase, orgId)
    : getOrg(supabase, org_name || user.username));

  // if specified org not found, fallback to personal org
  if (org_name && !org) {
    org = await getOrg(supabase, user.username);
  }

  if (!org) {
    console.error(
      '[api/device]',
      `Org "${org_name || user.username}" for user "${user.username}" not found`,
    );
    return NextResponse.json({}, { status: 404 });
  }

  // get all suitable apps in the org
  const apps = org.apps.filter((app) => app.api_key && !app.deleted_at);

  // get specified app in the org
  const app = app_name
    ? apps.find((app) => app.name === app_name) || apps[0]
    : apps[0];

  if (!app) {
    console.error(
      '[api/device]',
      `App ${app_name ? '"' + app_name + '" ' : ''}in org "${org_name || user.username}" not found`,
    );
    return NextResponse.json({}, { status: 404 });
  }

  return NextResponse.json(
    {
      ...user,
      org: {
        id: org.id,
        name: org.name,
      },
      app: {
        id: app.id,
        name: app.name,
        api_key: app.api_key,
      },
    },
    { status: 200 },
  );
});

async function getOrg(supabase: SupabaseClient<Database>, orgName: string) {
  const { data: org } = await supabase
    .from('orgs')
    .select('id, name, apps!org_id(id, deleted_at, name, api_key)')
    .eq('name_lowercase', orgName.toLowerCase())
    .maybeSingle();

  return org;
}

async function getOrgById(supabase: SupabaseClient<Database>, orgId: number) {
  const { data: org } = await supabase
    .from('orgs')
    .select('id, name, apps!org_id(id, deleted_at, name, api_key)')
    .eq('id', orgId)
    .maybeSingle();

  return org;
}

