        use std::fmt::Write;

        let app = self.get_app(org_app).await?;
        let mut url = format!(
            "{}/v1/apps/{}/deployments/{}/logs?limit={}",
            self.base_url, app.id, deployment_id, limit
        );
        if let Some(s) = since {
            let _ = write!(url, "&since={s}");
