    // ========================================================================
    // Regions & Images
    // ========================================================================

    pub async fn list_regions(&self, env: Option<&str>) -> Result<RegionsResponse> {
        use std::fmt::Write;

        let mut url = format!("{}/v1/regions", self.base_url);
        if let Some(e) = env {
