143→impl TableRow for SnapshotTableRow {
144→    fn headers() -> Vec<&'static str> {
145→        vec!["ID", "TIMESTAMP", "SIZE", "ROWS", "CHECKSUM", "CURRENT"]
146→    }
147→
148→    fn values(&self) -> Vec<String> {
149→        vec![
150→            self.id.to_string(),
151→            self.timestamp.clone(),
152→            self.size.clone(),
153→            self.rows.clone(),
154→            self.checksum.clone(),
155→            self.current.clone(),
156→        ]
157→    }
158→}
159→
160→/// Execute the acceleration command.
161→pub async fn execute(ctx: &RuntimeContext, args: &AccelerationArgs) -> Result<()> {
162→    if ctx.is_cloud() {
163→        tracing::error!("`spice acceleration` does not support `--cloud`.");
164→        return Ok(());
165→    }
166→
167→    match &args.command {
168→        AccelerationCommand::Snapshots(snap_args) => execute_snapshots(ctx, snap_args).await,
169→        AccelerationCommand::Snapshot(snap_args) => execute_snapshot(ctx, snap_args).await,
170→        AccelerationCommand::SetSnapshot(snap_args) => execute_set_snapshot(ctx, snap_args).await,
171→    }
172→}
173→
174→/// Execute the snapshots subcommand.
175→async fn execute_snapshots(ctx: &RuntimeContext, args: &SnapshotsArgs) -> Result<()> {
176→    let url = format!("/v1/datasets/{}/acceleration/snapshots", args.dataset);
177→
178→    let response = ctx.get(&url).await.map_err(|_| {
179→        RuntimeUnavailableSnafu {
180→            endpoint: ctx.http_endpoint().to_string(),
181→        }
182→        .build()
183→    })?;
184→
185→    if !response.status().is_success() {
186→        let status = response.status();
187→        let body = response.text().await.unwrap_or_default();
188→        tracing::error!("Failed to list snapshots: {} - {}", status, body);
189→        return Ok(());
190→    }
191→
192→    let summary: SnapshotSummary = response.json().await.map_err(|e| {
193→        InvalidResponseSnafu {
194→            message: format!("Failed to parse snapshots response: {e}"),
195→        }
196→        .build()
197→    })?;
198→
199→    if matches!(args.output, OutputFormat::Json) {
200→        return write_json(&summary);
201→    }
202→
203→    if summary.snapshots.is_empty() {
204→        println!("No snapshots found for dataset {}", args.dataset);
205→        println!("Location: {}", summary.location);
206→        return Ok(());
207→    }
208→
209→    println!("Dataset: {}", summary.dataset_name);
210→    println!("Location: {}", summary.location);
211→    if let Some(ref engine) = summary.engine {
212→        println!("Engine: {engine}");
213→    }
214→    if let Some(current_id) = summary.current_snapshot_id {
215→        println!("Current Snapshot ID: {current_id}");
216→    }
217→    let last_updated = format_timestamp_ms(summary.last_updated_ms);
218→    println!("Last Updated: {last_updated}");
219→    println!();
220→
221→    // Convert to table rows
222→    let rows: Vec<SnapshotTableRow> = summary
223→        .snapshots
224→        .iter()
225→        .map(|s| SnapshotTableRow {
226→            id: s.snapshot_id,
227→            timestamp: format_timestamp_ms(s.timestamp_ms),
228→            size: format_bytes(s.size_bytes),
229→            rows: s.row_count.map_or("-".to_string(), format_number),
230→            checksum: truncate_checksum(&s.checksum),
231→            current: if s.is_current {
232→                "✓".to_string()
233→            } else {
234→                String::new()
235→            },
236→        })
237→        .collect();
238→
239→    write_table(&rows);
240→
241→    Ok(())
242→}
243→
244→/// Execute the snapshot subcommand.
245→async fn execute_snapshot(ctx: &RuntimeContext, args: &SnapshotArgs) -> Result<()> {
246→    let url = format!(
247→        "/v1/datasets/{}/acceleration/snapshots/{}",
248→        args.dataset, args.snapshot_id
249→    );
250→
251→    let response = ctx.get(&url).await.map_err(|_| {
252→        RuntimeUnavailableSnafu {
253→            endpoint: ctx.http_endpoint().to_string(),
254→        }
255→        .build()
256→    })?;
257→
258→    if !response.status().is_success() {
259→        let status = response.status();
260→        let body = response.text().await.unwrap_or_default();
261→        tracing::error!("Failed to get snapshot: {} - {}", status, body);
262→        return Ok(());
263→    }
264→
265→    let snapshot: SnapshotInfo = response.json().await.map_err(|e| {
266→        InvalidResponseSnafu {
267→            message: format!("Failed to parse snapshot response: {e}"),
268→        }
269→        .build()
270→    })?;
271→
272→    if matches!(args.output, OutputFormat::Json) {
273→        return write_json(&snapshot);
274→    }
275→
276→    println!("Snapshot ID: {}", snapshot.snapshot_id);
277→    println!("Timestamp: {}", format_timestamp_ms(snapshot.timestamp_ms));
278→    println!("Location: {}", snapshot.location);
279→    if let Some(ref engine) = snapshot.engine {
280→        println!("Engine: {engine}");
281→    }
282→    println!(
283→        "Size: {} ({} bytes)",
284→        format_bytes(snapshot.size_bytes),
285→        snapshot.size_bytes
286→    );
287→    if let Some(row_count) = snapshot.row_count {
288→        println!("Rows: {}", format_number(row_count));
289→    }
290→    println!(
291→        "Checksum ({}): {}",
292→        snapshot.checksum_algorithm, snapshot.checksum
293→    );
294→    println!("Is Current: {}", snapshot.is_current);
295→
296→    Ok(())
297→}
