336→/// Format a timestamp in milliseconds as an RFC3339 string.
337→fn format_timestamp_ms(ms: i64) -> String {
338→    use std::time::{Duration, UNIX_EPOCH};
339→
340→    let duration = Duration::from_millis(ms as u64);
341→    let datetime = UNIX_EPOCH + duration;
342→
343→    // Format as RFC3339-like string
344→    let secs = datetime
345→        .duration_since(UNIX_EPOCH)
346→        .map(|d| d.as_secs())
347→        .unwrap_or(0);
348→    let naive =
349→        chrono::DateTime::from_timestamp(secs as i64, 0).unwrap_or(chrono::DateTime::UNIX_EPOCH);
350→    naive.format("%Y-%m-%dT%H:%M:%SZ").to_string()
351→}
352→
353→/// Format bytes as a human-readable string.
354→fn format_bytes(bytes: u64) -> String {
355→    const KB: u64 = 1024;
356→    const MB: u64 = KB * 1024;
357→    const GB: u64 = MB * 1024;
358→    const TB: u64 = GB * 1024;
359→
360→    if bytes >= TB {
361→        format!("{:.1} TB", bytes as f64 / TB as f64)
362→    } else if bytes >= GB {
363→        format!("{:.1} GB", bytes as f64 / GB as f64)
364→    } else if bytes >= MB {
365→        format!("{:.1} MB", bytes as f64 / MB as f64)
366→    } else if bytes >= KB {
367→        format!("{:.1} KB", bytes as f64 / KB as f64)
368→    } else {
369→        format!("{bytes} B")
370→    }
371→}
372→
373→/// Format a number with comma separators.
374→fn format_number(n: u64) -> String {
375→    let s = n.to_string();
376→    let mut result = String::new();
377→    for (i, c) in s.chars().rev().enumerate() {
378→        if i > 0 && i % 3 == 0 {
379→            result.insert(0, ',');
380→        }
381→        result.insert(0, c);
382→    }
383→    result
384→}
385→
386→/// Truncate a checksum for display.
387→fn truncate_checksum(checksum: &str) -> String {
388→    if checksum.len() > 16 {
389→        format!("{}...", &checksum[..16])
390→    } else {
391→        checksum.to_string()
392→    }
393→}
