 17→//! `spice eval` command - Run model evaluation.
 18→
 19→use crate::RuntimeContext;
 20→use crate::error::{InvalidArgumentSnafu, InvalidResponseSnafu, Result};
 21→use crate::output::{OutputFormat, TableOutput, write_json};
 22→use clap::Args;
 23→use serde::{Deserialize, Serialize};
 24→use snafu::ensure;
 25→use std::collections::HashMap;
 26→
 27→/// Arguments for the `eval` command.
 28→#[derive(Args, Debug)]
 29→pub struct EvalArgs {
 30→    /// Name of the eval to run
 31→    pub eval_name: String,
 32→
 33→    /// Model to evaluate
 34→    #[arg(long, required = true)]
 35→    pub model: String,
 36→
 37→    /// Output format
 38→    #[arg(long, short = 'o', default_value = "table")]
 39→    pub output: OutputFormat,
 40→}
 41→
 42→/// Request body for eval API.
 43→#[derive(Debug, Serialize)]
 44→struct EvalRequest {
 45→    model: String,
 46→}
 47→
 48→/// Response from eval API.
 49→#[derive(Debug, Deserialize, Serialize)]
 50→struct EvalResponse {
 51→    id: String,
 52→    created_at: String,
 53→    dataset: String,
 54→    model: String,
 55→    status: String,
 56→    scorers: Vec<String>,
 57→    metrics: HashMap<String, f64>,
 58→}
 59→
 60→/// Execute the `eval` command.
 61→///
 62→/// # Errors
 63→///
 64→/// Returns an error if the eval name is empty, model is empty, or the API request fails.
 65→pub async fn execute(ctx: &RuntimeContext, args: &EvalArgs) -> Result<()> {
 66→    ensure!(
 67→        !args.eval_name.is_empty(),
 68→        InvalidArgumentSnafu {
 69→            message: "eval name is required"
 70→        }
 71→    );
 72→
 73→    ensure!(
 74→        !args.model.is_empty(),
 75→        InvalidArgumentSnafu {
 76→            message: "model is required"
 77→        }
 78→    );
 79→
 80→    let request = EvalRequest {
 81→        model: args.model.clone(),
 82→    };
 83→
 84→    let response = ctx
 85→        .post_json(&format!("/v1/evals/{}", args.eval_name), &request)
 86→        .await?;
 87→
 88→    if !response.status().is_success() {
 89→        let status = response.status();
 90→        let text = response.text().await.unwrap_or_default();
 91→        return Err(InvalidResponseSnafu {
 92→            message: format!("eval request failed with status {status}: {text}"),
 93→        }
 94→        .build());
 95→    }
 96→
 97→    let results: Vec<EvalResponse> = response.json().await.map_err(|e| {
 98→        InvalidResponseSnafu {
 99→            message: format!("Failed to parse eval response: {e}"),
100→        }
101→        .build()
102→    })?;
103→
104→    if results.is_empty() {
105→        println!("No evaluation results.");
106→        return Ok(());
107→    }
108→
109→    if matches!(args.output, OutputFormat::Json) {
110→        return write_json(&results);
111→    }
112→
113→    // Display results in a table
114→    let mut table = TableOutput::new(vec![
115→        "ID",
116→        "Created At",
117→        "Dataset",
118→        "Model",
119→        "Status",
120→        "Scorers",
121→        "Metrics",
122→    ]);
123→
124→    for result in results {
125→        let scorers = result.scorers.join(", ");
126→        let metrics = result
127→            .metrics
128→            .iter()
129→            .map(|(k, v)| format!("{k}: {v:.4}"))
130→            .collect::<Vec<_>>()
131→            .join(", ");
132→
133→        table.add_row(vec![
134→            result.id,
135→            result.created_at,
136→            result.dataset,
137→            result.model,
138→            result.status,
139→            scorers,
140→            metrics,
141→        ]);
142→    }
143→
144→    println!("{table}");
145→
146→    Ok(())
147→}
