 17→//! `spice search` command - Semantic search REPL.
 18→
 19→use crate::context::RuntimeContext;
 20→use crate::error::{ConnectionFailedSnafu, InvalidResponseSnafu, Result};
 21→use crate::output::{OutputFormat, TableOutput};
 22→use clap::Args;
 23→use repl::util::{Spinner, create_editor_with_history, save_history};
 24→use serde::{Deserialize, Serialize};
 25→use snafu::ResultExt;
 26→use std::collections::HashMap;
 27→use std::io::{self, Write};
 28→
 29→/// Arguments for the `search` command.
 30→#[derive(Args, Debug)]
 31→pub struct SearchArgs {
 32→    /// Limit number of search results
 33→    #[arg(long, short, default_value = "10")]
 34→    pub limit: u32,
 35→
 36→    /// Control whether the results cache is used for searches
 37→    #[arg(long, default_value = "cache", value_parser = ["cache", "no-cache"])]
 38→    pub cache_control: String,
 39→
 40→    /// Model to use for search
 41→    #[arg(long)]
 42→    pub model: Option<String>,
 43→
 44→    /// Remote Spice instance HTTP endpoint (e.g., `http://localhost:8090`)
 45→    #[arg(long)]
 46→    pub endpoint: Option<String>,
 47→
 48→    /// Custom HTTP headers in format 'Key:Value' (can be specified multiple times)
 49→    #[arg(long = "headers", value_name = "KEY:VALUE")]
 50→    pub custom_headers: Vec<String>,
 51→
 52→    /// Output format
 53→    #[arg(long, short = 'o', default_value = "table")]
 54→    pub output: OutputFormat,
 55→}
 56→
 57→/// Request body for the search endpoint.
 58→#[derive(Serialize)]
 59→struct SearchRequest {
 60→    text: String,
 61→    #[serde(skip_serializing_if = "Option::is_none")]
 62→    datasets: Option<Vec<String>>,
 63→    limit: u32,
 64→    #[serde(skip_serializing_if = "Option::is_none")]
 65→    additional_columns: Option<Vec<String>>,
 66→    #[serde(skip_serializing_if = "Option::is_none")]
 67→    r#where: Option<String>,
 68→    #[serde(skip_serializing_if = "Option::is_none")]
 69→    model: Option<String>,
 70→}
 71→
 72→/// A single search match result.
 73→#[derive(Deserialize, Serialize)]
 74→struct SearchMatch {
 75→    matches: HashMap<String, StringOrSlice>,
 76→    score: f64,
 77→    dataset: String,
 78→    #[serde(default)]
 79→    primary_key: HashMap<String, serde_json::Value>,
 80→}
 81→
 82→/// Response from the search endpoint.
 83→#[derive(Deserialize, Serialize)]
 84→struct SearchResponse {
 85→    results: Vec<SearchMatch>,
 86→    duration_ms: u64,
 87→}
 88→
 89→/// Full search result with metadata.
 90→struct SearchResult {
 91→    response: SearchResponse,
 92→    from_cache: bool,
 93→}
 94→
 95→/// A string or array of strings (for flexible JSON parsing).
 96→#[derive(Deserialize, Serialize)]
 97→#[serde(untagged)]
 98→enum StringOrSlice {
 99→    Single(String),
100→    Multiple(Vec<String>),
101→}
102→
103→impl StringOrSlice {
104→    fn as_vec(&self) -> Vec<&str> {
105→        match self {
106→            Self::Single(s) => vec![s.as_str()],
107→            Self::Multiple(v) => v.iter().map(String::as_str).collect(),
108→        }
109→    }
110→}
111→
112→/// Execute the `search` command.
113→///
114→/// # Errors
115→///
116→/// Returns an error if the API requests fail or input/output fails.
117→pub async fn execute(ctx: &RuntimeContext, args: &SearchArgs) -> Result<()> {
118→    if args.output == OutputFormat::Table {
119→        println!("Welcome to the Spice.ai search REPL! Enter your search queries.");
120→        println!();
121→    }
122→
123→    run_repl(ctx, args).await
124→}
125→
126→/// Run the REPL loop.
127→async fn run_repl(ctx: &RuntimeContext, args: &SearchArgs) -> Result<()> {
128→    let (mut rl, history_path) = create_editor_with_history("search_history.txt").map_err(|e| {
129→        InvalidResponseSnafu {
130→            message: e.to_string(),
131→        }
132→        .build()
133→    })?;
134→
135→    loop {
136→        let readline = rl.readline("search> ");
137→        let user_input = match readline {
138→            Ok(line) => line,
139→            Err(
140→                rustyline::error::ReadlineError::Interrupted | rustyline::error::ReadlineError::Eof,
141→            ) => {
142→                break;
143→            }
144→            Err(e) => {
145→                eprintln!("Error reading input: {e}");
146→                continue;
147→            }
148→        };
149→
150→        let query = user_input.trim();
151→        if query.is_empty() {
152→            println!("Enter a search query.");
153→            continue;
154→        }
155→
156→        // Add to history
157→        let _ = rl.add_history_entry(query);
158→
159→        // Handle exit commands
160→        if query == "exit" || query == "quit" || query == ".exit" || query == ".quit" {
161→            break;
162→        }
163→
164→        // Handle clear command
165→        if query.to_lowercase() == ".clear" {
166→            print!("\x1b[H\x1b[2J");
167→            let _ = io::stdout().flush();
168→            continue;
169→        }
170→
171→        // Execute the search with spinner
172→        match send_search_request_with_spinner(ctx, query, args).await {
173→            Ok(result) => {
174→                display_results(&result.response, args.output);
175→                #[expect(clippy::cast_precision_loss)]
176→                let duration_secs = result.response.duration_ms as f64 / 1000.0;
177→                let cached_str = if result.from_cache { " (cached)" } else { "" };
178→                if args.output == OutputFormat::Table {
179→                    println!(
180→                        "\nTime: {duration_secs:.3} seconds. {} results{cached_str}.",
181→                        result.response.results.len()
182→                    );
183→                    println!();
184→                }
185→            }
186→            Err(e) => {
187→                eprintln!("\x1b[31mError\x1b[0m {e}");
188→            }
189→        }
190→    }
191→
192→    // Save history
193→    save_history(&mut rl, history_path.as_ref());
194→
195→    Ok(())
196→}
197→
198→/// Send a request to the search endpoint with spinner.
199→async fn send_search_request_with_spinner(
200→    ctx: &RuntimeContext,
201→    query: &str,
202→    args: &SearchArgs,
203→) -> Result<SearchResult> {
204→    let spinner = Spinner::start();
205→
206→    let result = send_search_request(ctx, query, args).await;
207→
208→    spinner.stop().await;
209→
210→    result
211→}
212→
213→/// Send a request to the search endpoint.
214→async fn send_search_request(
215→    ctx: &RuntimeContext,
216→    query: &str,
217→    args: &SearchArgs,
218→) -> Result<SearchResult> {
219→    // Use endpoint override if provided, otherwise use context's endpoint
220→    let base_url = args
221→        .endpoint
222→        .as_deref()
223→        .unwrap_or_else(|| ctx.http_endpoint());
224→    let url = format!("{base_url}/v1/search");
225→
226→    let body = SearchRequest {
227→        text: query.to_string(),
228→        datasets: None,
229→        limit: args.limit,
230→        additional_columns: None,
231→        r#where: None,
232→        model: args.model.clone(),
233→    };
234→
235→    let mut request = ctx
236→        .http_client()
237→        .post(&url)
238→        .header("Content-Type", "application/json")
239→        .header("Cache-Control", &args.cache_control)
240→        .json(&body);
241→
242→    for (key, value) in ctx.get_headers() {
243→        request = request.header(&key, &value);
244→    }
245→
246→    // Add custom headers from command line
247→    for header in &args.custom_headers {
248→        if let Some((key, value)) = header.split_once(':') {
249→            request = request.header(key.trim(), value.trim());
250→        }
251→    }
252→
253→    let response = request
254→        .send()
255→        .await
256→        .context(ConnectionFailedSnafu { endpoint: &url })?;
257→
258→    let status = response.status();
259→    // Check cache status header
260→    let cache_status = response
261→        .headers()
262→        .get("Search-Results-Cache-Status")
263→        .and_then(|v| v.to_str().ok())
264→        .map(String::from);
265→    let from_cache = matches!(cache_status.as_deref(), Some("HIT" | "STALE"));
266→
267→    let text = response.text().await.unwrap_or_default();
268→
269→    if !status.is_success() {
270→        return Err(InvalidResponseSnafu {
271→            message: format!("Search failed: {text}"),
272→        }
273→        .build());
274→    }
275→
276→    let response: SearchResponse = serde_json::from_str(&text).map_err(|e| {
277→        InvalidResponseSnafu {
278→            message: format!("Failed to parse response: {e}"),
279→        }
280→        .build()
281→    })?;
282→
283→    Ok(SearchResult {
284→        response,
285→        from_cache,
286→    })
287→}
288→
289→/// Display search results in a table.
290→fn display_results(response: &SearchResponse, output: OutputFormat) {
291→    if response.results.is_empty() {
292→        println!("No results.");
293→        return;
294→    }
295→
296→    if output == OutputFormat::Json {
297→        match serde_json::to_string_pretty(response) {
298→            Ok(json) => println!("{json}"),
299→            Err(e) => eprintln!("Failed to serialize search results: {e}"),
300→        }
301→        return;
302→    }
303→
304→    // Collect all primary key names
305→    let mut pk_names: Vec<String> = Vec::new();
306→    for result in &response.results {
307→        for key in result.primary_key.keys() {
308→            if !pk_names.contains(key) {
309→                pk_names.push(key.clone());
310→            }
311→        }
312→    }
313→    pk_names.sort();
314→
315→    // Build table
316→    let headers = if pk_names.is_empty() {
317→        vec!["Rank", "Match", "Score", "Dataset"]
318→    } else {
319→        vec!["Rank", "Key", "Match", "Score", "Dataset"]
320→    };
321→
322→    let mut table = TableOutput::new(headers);
323→
324→    for (i, result) in response.results.iter().enumerate() {
325→        let rank = format!("{}", i + 1);
326→        let score = format!("{:.4}", result.score);
327→        let dataset = result.dataset.clone();
328→
329→        // Format primary key
330→        let pk_value = if pk_names.is_empty() {
331→            String::new()
332→        } else {
333→            pk_names
334→                .iter()
335→                .filter_map(|k| result.primary_key.get(k).map(|v| format!("{v}")))
336→                .collect::<Vec<_>>()
337→                .join(", ")
338→        };
339→
340→        // Format matches - show first 3 lines
341→        let match_text = format_matches(&result.matches);
342→
343→        if pk_names.is_empty() {
344→            table.add_row(vec![rank, match_text, score, dataset]);
345→        } else {
346→            table.add_row(vec![rank, pk_value, match_text, score, dataset]);
347→        }
348→    }
349→
350→    println!("{table}");
351→}
352→
353→/// Format match text, truncating to first 3 lines.
354→fn format_matches(matches: &HashMap<String, StringOrSlice>) -> String {
355→    let mut texts: Vec<String> = Vec::new();
356→
357→    for (col, values) in matches {
358→        for value in values.as_vec() {
359→            // Take first 3 lines
360→            let lines: Vec<&str> = value.lines().take(3).collect();
361→            let truncated = lines.join("\n").replace('\r', "");
362→
363→            if matches.len() > 1 {
364→                texts.push(format!("{col}: {truncated}"));
365→            } else {
366→                texts.push(truncated);
367→            }
368→        }
369→    }
370→
371→    texts.join("; ")
372→}
