 17→//! `spice trace` command - Return traces for operations in Spice.
 18→
 19→use crate::RuntimeContext;
 20→use crate::error::{InvalidArgumentSnafu, InvalidResponseSnafu, Result};
 21→use crate::output::TableOutput;
 22→use chrono::{DateTime, Utc};
 23→use clap::{Args, ValueEnum};
 24→use serde::{Deserialize, Serialize};
 25→use snafu::ensure;
 26→use std::collections::HashMap;
 27→
 28→/// Supported trace task types.
 29→const SUPPORTED_TRACE_TASKS: &[&str] = &[
 30→    "ai",
 31→    "ai_chat",
 32→    "acceleration_refresh",
 33→    "ai_completion",
 34→    "eval_run",
 35→    "nsql",
 36→    "sql_query",
 37→    "tool_use::search",
 38→    "tool_use::list_datasets",
 39→    "tool_use::load_memory",
 40→    "tool_use::sample_data",
 41→    "tool_use::sql",
 42→    "tool_use::store_memory",
 43→    "tool_use::table_schema",
 44→    "search",
 45→    "scheduled_worker",
 46→    "text_embed",
 47→];
 48→
 49→/// Output format for trace command.
 50→#[derive(Debug, Clone, Copy, Default, ValueEnum)]
 51→pub enum OutputFormat {
 52→    /// Display results as a table (default)
 53→    #[default]
 54→    Table,
 55→    /// Output results as pretty-printed JSON
 56→    Json,
 57→    /// Output the SQL query that would be executed
 58→    Sql,
 59→}
 60→
 61→/// Arguments for the `trace` command.
 62→#[derive(Args, Debug)]
 63→#[command(
 64→    about = "Return a user friendly trace into an operation that occurred in Spice",
 65→    long_about = format!(
 66→        "Return a user friendly trace into an operation that occurred in Spice\n\n\
 67→        Available operations:\n  {}",
 68→        SUPPORTED_TRACE_TASKS.join(", ")
 69→    )
 70→)]
 71→pub struct TraceArgs {
 72→    /// The task type to trace
 73→    pub task: String,
 74→
 75→    /// Return the trace with the given id
 76→    #[arg(long)]
 77→    pub id: Option<String>,
 78→
 79→    /// Return the trace with the given trace id
 80→    #[arg(long)]
 81→    pub trace_id: Option<String>,
 82→
 83→    /// Include input data in the trace
 84→    #[arg(long)]
 85→    pub include_input: bool,
 86→
 87→    /// Include output data in the trace
 88→    #[arg(long)]
 89→    pub include_output: bool,
 90→
 91→    /// Truncate input/output data (default 80 when set without value)
 92→    #[arg(long, default_missing_value = "80")]
 93→    pub truncate: Option<usize>,
 94→
 95→    /// Output format
 96→    #[arg(long, short = 'o', value_enum, default_value = "table")]
 97→    pub output: OutputFormat,
 98→}
 99→
100→/// Task history record from the runtime.
101→#[derive(Debug, Deserialize, Serialize)]
102→struct TaskHistory {
103→    trace_id: String,
104→    span_id: String,
105→    parent_span_id: Option<String>,
106→    task: String,
107→    input: String,
108→    captured_output: Option<String>,
109→    start_time: DateTime<Utc>,
110→    end_time: DateTime<Utc>,
111→    execution_duration_ms: f64,
112→    error_message: Option<String>,
113→    labels: HashMap<String, String>,
114→}
115→
116→/// Tree node for trace hierarchy.
117→struct TreeNode {
118→    task_history: TaskHistory,
119→    children: Vec<TreeNode>,
120→}
121→
122→/// Row for display with tree prefix.
123→struct TaskHistoryRow {
124→    tree: String,
125→    task: TaskHistory,
126→}
127→
128→/// Execute the `trace` command.
129→///
130→/// # Errors
131→///
132→/// Returns an error if the task type is invalid or the API request fails.
133→pub async fn execute(ctx: &RuntimeContext, args: &TraceArgs) -> Result<()> {
134→    // Validate task type
135→    ensure!(
136→        is_valid_trace_task(&args.task),
137→        InvalidArgumentSnafu {
138→            message: format!(
139→                "invalid trace type '{}'. Available: {}",
140→                args.task,
141→                SUPPORTED_TRACE_TASKS.join(", ")
142→            )
143→        }
144→    );
145→
146→    // Build the SQL query filter
147→    let filter = get_trace_filter(&args.task, args.id.as_deref(), args.trace_id.as_deref());
148→    let sql_query =
149→        format!("SELECT * FROM runtime.task_history WHERE {filter} ORDER BY start_time asc");
150→
151→    // If SQL output requested, just print the query
152→    if matches!(args.output, OutputFormat::Sql) {
153→        println!("{sql_query}");
154→        return Ok(());
155→    }
156→
157→    // Execute SQL query
158→    let traces = sql_request_to_traces(ctx, &sql_query).await?;
159→
160→    if traces.is_empty() {
161→        eprintln!("Error: No events found");
162→        return Ok(());
163→    }
164→
165→    // JSON output: emit raw trace records
166→    if matches!(args.output, OutputFormat::Json) {
167→        return crate::output::write_json(&traces);
168→    }
169→
170→    // Build tree and display
171→    let rows = tree_rows_from_traces(traces);
172→    display_trace_table(
173→        &rows,
174→        args.include_input,
175→        args.include_output,
176→        args.truncate,
177→    );
178→
179→    Ok(())
180→}
181→
182→fn is_valid_trace_task(task: &str) -> bool {
183→    SUPPORTED_TRACE_TASKS.contains(&task)
184→}
185→
186→/// Quote a SQL string value (escape single quotes).
187→fn quote_sql_string(s: &str) -> String {
188→    let escaped = s.replace('\'', "''");
189→    format!("'{escaped}'")
190→}
191→
192→/// Build the SQL filter based on provided arguments.
193→fn get_trace_filter(task: &str, id: Option<&str>, trace_id: Option<&str>) -> String {
194→    if let Some(id) = id {
195→        format!(
196→            "trace_id=(SELECT trace_id from runtime.task_history where labels.id={})",
197→            quote_sql_string(id)
198→        )
199→    } else if let Some(trace_id) = trace_id {
200→        format!("trace_id={}", quote_sql_string(trace_id))
201→    } else {
202→        // Use last trace by default
203→        format!(
204→            "trace_id=(SELECT trace_id from runtime.task_history where task={} order by start_time desc limit 1)",
205→            quote_sql_string(task)
206→        )
207→    }
208→}
209→
210→/// Execute SQL query and parse results into `TaskHistory` records.
211→///
212→/// # Errors
213→///
214→/// Returns an error if the HTTP request fails or the response cannot be parsed.
215→async fn sql_request_to_traces(ctx: &RuntimeContext, sql: &str) -> Result<Vec<TaskHistory>> {
216→    let url = format!("{}/v1/sql", ctx.http_endpoint());
217→
218→    let mut request = ctx
219→        .http_client()
220→        .post(&url)
221→        .header("Content-Type", "text/plain")
222→        .header("Accept", "application/json")
223→        .body(sql.to_string());
224→
225→    for (key, value) in ctx.get_headers() {
226→        request = request.header(&key, &value);
227→    }
228→
229→    let response = request
230→        .send()
231→        .await
232→        .map_err(|e| crate::error::Error::ConnectionFailed {
233→            endpoint: url.clone(),
234→            source: e,
235→        })?;
236→
237→    if !response.status().is_success() {
238→        let status = response.status();
239→        let text = response.text().await.unwrap_or_default();
240→
241→        // Special case for task_history disabled
242→        if text.contains("table 'spice.runtime.task_history' not found") {
243→            eprintln!(
244→                "Trace functionality requires task history, which is disabled. Set `runtime.task_history: true` in the Spicepod YAML file and retry. Details: https://spiceai.org/docs/reference/spicepod/runtime#runtimetask_history"
245→            );
246→            return Ok(vec![]);
247→        }
248→
249→        return Err(InvalidResponseSnafu {
250→            message: format!("SQL request failed with status {status}: {text}"),
251→        }
252→        .build());
253→    }
254→
255→    let text = response.text().await.map_err(|e| {
256→        InvalidResponseSnafu {
257→            message: format!("Failed to read response: {e}"),
258→        }
259→        .build()
260→    })?;
261→
262→    if text.is_empty() {
263→        return Ok(vec![]);
264→    }
265→
266→    serde_json::from_str(&text).map_err(|e| {
267→        InvalidResponseSnafu {
268→            message: format!("Failed to parse response: {e}"),
269→        }
270→        .build()
271→    })
272→}
273→
274→/// Recursively build a tree node from the node map.
275→fn build_tree_node(
276→    span_id: &str,
277→    node_map: &mut HashMap<String, TreeNode>,
278→    children_by_parent: &HashMap<String, Vec<String>>,
279→) -> Option<TreeNode> {
280→    let mut node = node_map.remove(span_id)?;
281→
282→    if let Some(child_ids) = children_by_parent.get(span_id) {
283→        let mut children: Vec<TreeNode> = child_ids
284→            .iter()
285→            .filter_map(|child_id| build_tree_node(child_id, node_map, children_by_parent))
286→            .collect();
287→
288→        // Sort children by start time
289→        children.sort_by(|a, b| a.task_history.start_time.cmp(&b.task_history.start_time));
290→
291→        node.children = children;
292→    }
293→
294→    Some(node)
295→}
296→
297→/// Build a hierarchical tree from `TaskHistory` entries.
298→fn build_trace_tree(tasks: Vec<TaskHistory>) -> Option<TreeNode> {
299→    if tasks.is_empty() {
300→        return None;
301→    }
302→
303→    // Create a lookup map for SpanID -> Node
304→    let mut node_map: HashMap<String, TreeNode> = tasks
305→        .into_iter()
306→        .map(|task| {
307→            let span_id = task.span_id.clone();
308→            (
309→                span_id,
310→                TreeNode {
311→                    task_history: task,
312→                    children: Vec::new(),
313→                },
314→            )
315→        })
316→        .collect();
317→
318→    // Find root and build parent-child relationships
319→    let mut root_span_id: Option<String> = None;
320→    let parent_child_pairs: Vec<(String, String)> = node_map
321→        .values()
322→        .filter_map(|node| {
323→            if let Some(parent_id) = &node.task_history.parent_span_id {
324→                Some((parent_id.clone(), node.task_history.span_id.clone()))
325→            } else {
326→                root_span_id = Some(node.task_history.span_id.clone());
327→                None
328→            }
329→        })
330→        .collect();
331→
332→    // Group children by parent
333→    let mut children_by_parent: HashMap<String, Vec<String>> = HashMap::new();
334→    for (parent_id, child_id) in parent_child_pairs {
335→        children_by_parent
336→            .entry(parent_id)
337→            .or_default()
338→            .push(child_id);
339→    }
340→
341→    root_span_id.and_then(|root_id| build_tree_node(&root_id, &mut node_map, &children_by_parent))
342→}
343→
344→/// Convert trace tree to display rows with tree formatting.
345→fn tree_rows_from_traces(traces: Vec<TaskHistory>) -> Vec<TaskHistoryRow> {
346→    let Some(tree) = build_trace_tree(traces) else {
347→        return vec![];
348→    };
349→
350→    let mut rows = Vec::new();
351→    recurse_through_tree(&mut rows, &tree, "", true);
352→    rows
353→}
354→
355→/// Recursively traverse tree and build formatted rows.
356→fn recurse_through_tree(
357→    rows: &mut Vec<TaskHistoryRow>,
358→    node: &TreeNode,
359→    indent: &str,
360→    is_last: bool,
361→) {
362→    let connector = if indent.is_empty() {
363→        ""
364→    } else if is_last {
365→        "└── "
366→    } else {
367→        "├── "
368→    };
369→
370→    rows.push(TaskHistoryRow {
371→        tree: format!("{indent}{connector}{}", node.task_history.task),
372→        task: TaskHistory {
373→            trace_id: node.task_history.trace_id.clone(),
374→            span_id: node.task_history.span_id.clone(),
375→            parent_span_id: node.task_history.parent_span_id.clone(),
376→            task: node.task_history.task.clone(),
377→            input: node.task_history.input.clone(),
378→            captured_output: node.task_history.captured_output.clone(),
379→            start_time: node.task_history.start_time,
380→            end_time: node.task_history.end_time,
381→            execution_duration_ms: node.task_history.execution_duration_ms,
382→            error_message: node.task_history.error_message.clone(),
383→            labels: node.task_history.labels.clone(),
384→        },
385→    });
386→
387→    let new_indent = if indent.is_empty() {
388→        String::new()
389→    } else if is_last {
390→        format!("{indent}  ")
391→    } else {
392→        format!("{indent}│ ")
393→    };
394→
395→    for (i, child) in node.children.iter().enumerate() {
396→        let child_is_last = i == node.children.len() - 1;
397→        recurse_through_tree(rows, child, &new_indent, child_is_last);
398→    }
399→}
400→
401→/// Display trace results as a table.
402→fn display_trace_table(
403→    rows: &[TaskHistoryRow],
404→    include_input: bool,
405→    include_output: bool,
406→    truncate: Option<usize>,
407→) {
408→    let mut headers = vec!["Tree", "Status", "Duration", "Span ID"];
409→
410→    if include_input {
411→        headers.push("Input");
412→    }
413→    if include_output {
414→        headers.push("Output");
415→    }
416→
417→    let mut table = TableOutput::new(headers);
418→
419→    for row in rows {
420→        let status = if row.task.error_message.is_none()
421→            || row
422→                .task
423→                .error_message
424→                .as_ref()
425→                .is_some_and(String::is_empty)
426→        {
427→            "OK".to_string()
428→        } else {
429→            "ERR".to_string()
430→        };
431→
432→        let duration = format!("{:>8.2}ms", row.task.execution_duration_ms);
433→
434→        let mut values = vec![row.tree.clone(), status, duration, row.task.span_id.clone()];
435→
436→        if include_input {
437→            let input = truncate_string(&row.task.input, truncate);
438→            values.push(input);
439→        }
440→
441→        if include_output {
442→            let output = row
443→                .task
444→                .captured_output
445→                .as_ref()
446→                .map_or_else(|| "<empty>".to_string(), |o| truncate_string(o, truncate));
447→            values.push(output);
448→        }
449→
450→        table.add_row(values);
451→    }
452→
453→    println!("{table}");
454→}
455→
456→/// Truncate a string with an indicator of how many characters were omitted.
457→fn truncate_string(s: &str, max_len: Option<usize>) -> String {
458→    if s.is_empty() {
459→        return "<empty>".to_string();
460→    }
461→
462→    match max_len {
463→        Some(max) if s.len() > max => {
464→            let omitted = s.len() - max;
465→            format!("{}... ({omitted} characters omitted)", &s[..max])
466→        }
467→        _ => s.to_string(),
468→    }
469→}
