 17→//! Version command implementation.
 18→
 19→use crate::context::RuntimeContext;
 20→use crate::error::Result;
 21→use crate::github::{GitHubClient, get_latest_release};
 22→use crate::output::{OutputFormat, write_json};
 23→use clap::Args;
 24→use std::fs;
 25→use std::path::PathBuf;
 26→use std::time::{Duration, SystemTime};
 27→
 28→/// Cache validity duration for version checks.
 29→const VERSION_CACHE_DURATION: Duration = Duration::from_secs(24 * 60 * 60); // 24 hours
 30→
 31→/// Arguments for the version command.
 32→#[derive(Args, Debug)]
 33→pub struct VersionArgs {
 34→    /// Show only the CLI version (no runtime version)
 35→    #[arg(long)]
 36→    cli_only: bool,
 37→
 38→    /// Output format
 39→    #[arg(long, short = 'o', default_value = "table")]
 40→    output: OutputFormat,
 41→}
 42→
 43→/// Get the CLI version string.
 44→#[must_use]
 45→pub fn cli_version() -> String {
 46→    let version = env!("CARGO_PKG_VERSION");
 47→    if cfg!(feature = "release") {
 48→        format!("v{version}")
 49→    } else {
 50→        let git_hash = option_env!("GIT_COMMIT_HASH").unwrap_or("unknown");
 51→        format!("v{version} ({git_hash})")
 52→    }
 53→}
 54→
 55→/// Get just the semver version (e.g., "v1.2.3").
 56→#[must_use]
 57→fn cli_semver() -> String {
 58→    let version = env!("CARGO_PKG_VERSION");
 59→    format!("v{version}")
 60→}
 61→
 62→/// Get the path to the cached version file.
 63→fn version_cache_path(ctx: &RuntimeContext) -> PathBuf {
 64→    ctx.spice_runtime_dir().join("cli_version.txt")
 65→}
 66→
 67→/// Check if a version string indicates a pre-release build.
 68→/// Matches Go CLI logic: prefix "local" or contains "build".
 69→fn is_prerelease(version: &str) -> bool {
 70→    version.starts_with("local") || version.contains("build")
 71→}
 72→
 73→/// Compare two semver versions. Returns true if `latest` is newer than `current`.
 74→fn is_newer_version(current: &str, latest: &str) -> bool {
 75→    // Strip 'v' prefix if present
 76→    let current = current.strip_prefix('v').unwrap_or(current);
 77→    let latest = latest.strip_prefix('v').unwrap_or(latest);
 78→
 79→    // Parse versions
 80→    let parse_version = |s: &str| -> (u32, u32, u32) {
 81→        let parts: Vec<&str> = s.split('-').next().unwrap_or(s).split('.').collect();
 82→        (
 83→            parts.first().and_then(|s| s.parse().ok()).unwrap_or(0),
 84→            parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(0),
 85→            parts.get(2).and_then(|s| s.parse().ok()).unwrap_or(0),
 86→        )
 87→    };
 88→
 89→    let current_parts = parse_version(current);
 90→    let latest_parts = parse_version(latest);
 91→
 92→    latest_parts > current_parts
 93→}
 94→
 95→/// Check for the latest CLI release version.
 96→async fn check_latest_version(ctx: &RuntimeContext) -> Option<String> {
 97→    let cache_path = version_cache_path(ctx);
 98→
 99→    // Check cache first - if valid, return cached version
100→    if let Ok(metadata) = fs::metadata(&cache_path)
101→        && let Ok(modified) = metadata.modified()
102→        && let Ok(age) = SystemTime::now().duration_since(modified)
103→        && age < VERSION_CACHE_DURATION
104→        && let Ok(version) = fs::read_to_string(&cache_path)
105→    {
106→        return Some(version.trim().to_string());
107→    }
108→
109→    // Fetch from GitHub
110→    let client = GitHubClient::new_runtime_client();
111→    let release = get_latest_release(&client).await.ok()?;
112→    let version = release.tag_name;
113→
114→    // Update cache
115→    if let Some(parent) = cache_path.parent() {
116→        let _ = fs::create_dir_all(parent);
117→    }
118→    let _ = fs::write(&cache_path, format!("{version}\n"));
119→
120→    Some(version)
121→}
122→
123→/// Display upgrade notification if a newer version is available.
124→async fn check_and_notify_upgrade(ctx: &RuntimeContext) {
125→    let current = cli_semver();
126→
127→    // Skip check for pre-release builds
128→    if is_prerelease(&current) {
129→        return;
130→    }
131→
132→    let Some(latest) = check_latest_version(ctx).await else {
133→        return;
134→    };
135→
136→    if is_newer_version(&current, &latest) {
137→        // Use green color for the version
138→        let green_version = format!("\x1b[92m{latest}\x1b[0m");
139→        println!();
140→        tracing::info!("CLI version {green_version} is now available!");
141→        tracing::info!("To upgrade, run \"spice upgrade\".");
142→    }
143→}
144→
145→/// Execute the version command.
146→///
147→/// # Errors
148→///
149→/// Returns an error if the runtime version cannot be determined.
150→pub async fn execute(ctx: &RuntimeContext, args: &VersionArgs) -> Result<()> {
151→    let cli = cli_version();
152→    let runtime = if args.cli_only {
153→        None
154→    } else {
155→        ctx.runtime_version().ok()
156→    };
157→
158→    match args.output {
159→        OutputFormat::Table => {
160→            println!("CLI version:     {cli}");
161→            if !args.cli_only {
162→                println!(
163→                    "Runtime version: {}",
164→                    runtime.as_deref().unwrap_or("not installed")
165→                );
166→            }
167→        }
168→        OutputFormat::Json => {
169→            write_json(&serde_json::json!({
170→                "cli": cli,
171→                "runtime": runtime,
172→            }))?;
173→        }
174→    }
175→
176→    // Check for newer version (non-blocking, failures are silent)
177→    check_and_notify_upgrade(ctx).await;
178→
179→    Ok(())
180→}
181→
182→#[cfg(test)]
183→mod tests {
184→    use super::*;
185→
186→    #[test]
187→    fn test_cli_version_format() {
188→        let version = cli_version();
189→        assert!(version.starts_with('v'));
190→        assert!(version.contains('('));
191→        assert!(version.contains(')'));
192→    }
193→
194→    #[test]
195→    fn test_is_newer_version() {
196→        // Basic version comparisons
197→        assert!(is_newer_version("v1.0.0", "v1.0.1"));
198→        assert!(is_newer_version("v1.0.0", "v1.1.0"));
199→        assert!(is_newer_version("v1.0.0", "v2.0.0"));
200→
201→        // Same version
202→        assert!(!is_newer_version("v1.0.0", "v1.0.0"));
203→
204→        // Older version
205→        assert!(!is_newer_version("v1.0.1", "v1.0.0"));
206→        assert!(!is_newer_version("v2.0.0", "v1.0.0"));
207→
208→        // Without 'v' prefix
209→        assert!(is_newer_version("1.0.0", "1.0.1"));
210→
211→        // Pre-release suffix is stripped (both compare as 1.0.0)
212→        assert!(!is_newer_version("v1.0.0-alpha", "v1.0.0"));
213→        assert!(is_newer_version("v1.0.0-alpha", "v1.0.1"));
214→    }
215→
216→    #[test]
217→    fn test_is_prerelease() {
218→        // Matches Go CLI: starts with "local" or contains "build"
219→        assert!(is_prerelease("local"));
220→        assert!(is_prerelease("local-dev"));
221→        assert!(is_prerelease("v1.0.0-build.123"));
222→        assert!(is_prerelease("v1.0.0+build"));
223→
224→        // These are NOT pre-release (matches Go behavior)
225→        assert!(!is_prerelease("v1.0.0"));
226→        assert!(!is_prerelease("v1.2.3"));
227→        assert!(!is_prerelease("v1.0.0-alpha")); // No "local" prefix or "build"
228→        assert!(!is_prerelease("v1.0.0-dev")); // No "local" prefix or "build"
229→    }
230→}
