 43→#[command(
 44→    about = "Submit an async query or start an interactive async query REPL",
 45→    long_about = r#"Submit an async SQL query or start an interactive REPL for managing async queries via the /v1/queries API.
 46→
 47→Queries are submitted asynchronously and the CLI auto-polls for completion. Press Ctrl+C to stop
 48→waiting for a query (the query continues running in the background).
 49→
 50→Async queries require cluster mode with scheduler.state_location configured."#
 51→)]
 52→pub struct QueryArgs {
 53→    /// SQL query to submit (if not provided, starts interactive REPL)
 54→    #[arg()]
 55→    sql: Option<String>,
 56→
 57→    /// Submit and return immediately without waiting for results
 58→    #[arg(long)]
 59→    no_wait: bool,
 60→
 61→    /// Maximum time to wait for query completion (e.g., "30s", "5m")
 62→    #[arg(long)]
 63→    timeout: Option<humantime::Duration>,
 64→
 65→    /// Output format (applies to query results when SQL is provided)
 66→    #[arg(long, short = 'o', default_value = "table")]
 67→    pub output: OutputFormat,
 68→
 69→    #[command(subcommand)]
 70→    command: Option<QuerySubcommand>,
 71→}
 72→
 73→#[derive(Subcommand, Debug)]
 74→pub enum QuerySubcommand {
 75→    /// List all queries
 76→    List {
 77→        /// Filter by status (pending, running, succeeded, failed, cancelled)
 78→        #[arg(long)]
 79→        status: Option<String>,
 80→
 81→        /// Maximum number of queries to return
 82→        #[arg(long, default_value = "100")]
 83→        limit: usize,
 84→
 85→        /// Output format
 86→        #[arg(long, short = 'o', default_value = "table")]
 87→        output: OutputFormat,
 88→    },
 89→
 90→    /// Check the status of a query
 91→    Status {
 92→        /// Query ID to check
 93→        query_id: String,
 94→
 95→        /// Output format
 96→        #[arg(long, short = 'o', default_value = "table")]
 97→        output: OutputFormat,
 98→    },
 99→
100→    /// Fetch and display results of a completed query
101→    Results {
102→        /// Query ID to get results for
103→        query_id: String,
104→
105→        /// Output format
106→        #[arg(long, short = 'o', default_value = "table")]
107→        output: OutputFormat,
108→    },
109→
110→    /// Cancel a running query
111→    Cancel {
112→        /// Query ID to cancel
113→        query_id: String,
114→    },
115→}
116→
117→/// Tracked query in the REPL session.
118→#[derive(Debug, Clone)]
119→struct TrackedQuery {
120→    query_id: String,
121→    sql: String,
122→    status: String,
123→    submitted_at: Instant,
124→}
