126→/// Build the spiceai SDK client from the runtime context.
127→async fn build_client(ctx: &RuntimeContext) -> Result<Arc<Client>> {
128→    let mut builder = ClientBuilder::new().http_url(ctx.http_endpoint());
129→
130→    if let Some(api_key) = ctx.api_key() {
131→        builder = builder.api_key(api_key);
132→    }
133→
134→    builder = builder.user_agent(ctx.user_agent());
135→
136→    let client = builder.build().await.map_err(|e| {
137→        let err_str = e.to_string();
138→        if err_str.contains("connection refused") {
139→            crate::error::Error::InvalidResponse {
140→                message: format!(
141→                    "Spice runtime is unavailable at {}. Is it running?",
142→                    ctx.http_endpoint()
143→                ),
144→            }
145→        } else {
146→            crate::error::Error::InvalidResponse { message: err_str }
147→        }
148→    })?;
149→
150→    Ok(Arc::new(client))
151→}
152→
153→/// Execute the query command.
154→pub async fn execute(ctx: &RuntimeContext, args: &QueryArgs) -> Result<()> {
155→    let client = build_client(ctx).await?;
156→
157→    // Handle subcommands
158→    if let Some(subcmd) = &args.command {
159→        return execute_subcommand(&client, subcmd).await;
160→    }
161→
162→    // If SQL argument provided, submit directly
163→    if let Some(sql) = &args.sql {
164→        return submit_and_wait(
165→            &client,
166→            sql,
167→            !args.no_wait,
168→            args.timeout.map(Into::into),
169→            args.output,
170→        )
171→        .await;
172→    }
173→
174→    // No argument, start REPL
175→    run_query_repl(&client).await
176→}
177→
178→async fn execute_subcommand(client: &Arc<Client>, cmd: &QuerySubcommand) -> Result<()> {
179→    match cmd {
180→        QuerySubcommand::List {
181→            status,
182→            limit,
183→            output,
184→        } => {
185→            let resp = client
186→                .queries(status.as_deref(), Some(*limit))
187→                .await
188→                .map_err(|e| crate::error::Error::InvalidResponse {
189→                    message: e.to_string(),
190→                })?;
191→
192→            if resp.queries.is_empty() {
193→                println!("No queries found.");
194→                return Ok(());
195→            }
196→
197→            if *output == OutputFormat::Json {
198→                let json_queries: Vec<serde_json::Value> = resp
199→                    .queries
200→                    .iter()
201→                    .map(|q| {
202→                        serde_json::json!({
203→                            "query_id": q.query_id,
204→                            "status": q.status.to_string(),
205→                            "created_at": q.created_at,
206→                            "sql_preview": q.sql_preview,
207→                        })
208→                    })
209→                    .collect();
210→                return write_json(&json_queries);
211→            }
212→
213→            let mut table = TableOutput::new(vec!["QUERY ID", "STATE", "CREATED", "SQL PREVIEW"]);
214→            for q in &resp.queries {
215→                let sql = if q.sql_preview.len() > 47 {
216→                    format!("{}...", &q.sql_preview[..47])
217→                } else {
218→                    q.sql_preview.clone()
219→                };
220→                table.add_row(vec![
221→                    q.query_id.clone(),
222→                    q.status.to_string(),
223→                    q.created_at.clone(),
224→                    sql,
225→                ]);
226→            }
227→            table.print();
228→            println!("\nTotal: {} queries", resp.queries.len());
229→        }
230→        QuerySubcommand::Status { query_id, output } => {
231→            let job =
232→                client
233→                    .get_query(query_id)
234→                    .map_err(|e| crate::error::Error::InvalidResponse {
235→                        message: e.to_string(),
236→                    })?;
237→            let info = job
238→                .info()
239→                .await
240→                .map_err(|e| crate::error::Error::InvalidResponse {
241→                    message: e.to_string(),
242→                })?;
243→            if *output == OutputFormat::Json {
244→                return write_json(&serde_json::json!({
245→                    "query_id": info.query_id,
246→                    "status": info.status.to_string(),
247→                    "error": info.error.as_ref().map(|e| &e.message),
248→                    "result": info.result.as_ref().map(|r| serde_json::json!({
249→                        "total_rows": r.total_rows,
250→                        "total_chunks": r.total_chunks,
251→                    })),
252→                }));
253→            }
254→            display_query_info(&info);
255→        }
256→        QuerySubcommand::Results { query_id, output } => {
257→            display_results(client, query_id, Duration::ZERO, *output).await?;
258→        }
259→        QuerySubcommand::Cancel { query_id } => {
260→            let info = client.cancel_query(query_id).await.map_err(|e| {
261→                crate::error::Error::InvalidResponse {
262→                    message: e.to_string(),
263→                }
264→            })?;
265→            println!(
266→                "Query {} cancelled (status: {})",
267→                info.query_id, info.status
268→            );
269→        }
270→    }
271→    Ok(())
272→}
273→
274→async fn submit_and_wait(
275→    client: &Arc<Client>,
276→    sql: &str,
277→    wait: bool,
278→    timeout: Option<Duration>,
279→    output: OutputFormat,
280→) -> Result<()> {
281→    let job = client
282→        .query(sql)
283→        .await
284→        .map_err(|e| crate::error::Error::InvalidResponse {
285→            message: e.to_string(),
286→        })?;
287→
288→    let query_id = job.id().to_string();
289→
290→    // Get initial status
291→    let initial_status = job
292→        .status()
293→        .await
294→        .map_err(|e| crate::error::Error::InvalidResponse {
295→            message: e.to_string(),
296→        })?;
297→
298→    println!("Submitted query: {query_id} ({initial_status})");
299→
300→    if !wait {
301→        println!("Check status with: spice query status {query_id}");
302→        println!("Get results with: spice query results {query_id}");
303→        return Ok(());
304→    }
305→
306→    println!("Waiting for completion... (Ctrl+C to stop waiting)");
307→
308→    let (final_status, was_cancelled, elapsed) =
309→        poll_for_completion(client, &query_id, timeout).await;
310→
311→    if was_cancelled {
312→        println!("\nStopped waiting. Query ID: {query_id}");
313→        return Ok(());
314→    }
315→
316→    if let Some(status) = final_status {
317→        if status.is_success() {
318→            display_results(client, &query_id, elapsed, output).await?;
319→        } else if status.is_failed() {
320→            let job =
321→                client
322→                    .get_query(&query_id)
323→                    .map_err(|e| crate::error::Error::InvalidResponse {
324→                        message: e.to_string(),
325→                    })?;
326→            let info = job.info().await.ok();
327→            if let Some(info) = info
328→                && let Some(err) = info.error
329→            {
330→                return Err(crate::error::Error::InvalidResponse {
331→                    message: format!("query failed: {}", err.message),
332→                });
333→            }
334→            return Err(crate::error::Error::InvalidResponse {
335→                message: "query failed".to_string(),
336→            });
337→        } else if status.is_cancelled() {
338→            println!("Query was cancelled.");
339→        }
340→    }
341→
342→    Ok(())
343→}
344→
345→async fn run_query_repl(client: &Arc<Client>) -> Result<()> {
346→    println!("Welcome to the Spice.ai async query REPL.");
347→    println!("Type SQL to submit a query, or .help for commands.");
348→    println!();
349→
350→    let config = Config::builder().build();
351→    let mut rl: Editor<(), _> =
352→        Editor::with_config(config).map_err(|e| crate::error::Error::InvalidResponse {
353→            message: format!("Failed to initialize REPL: {e}"),
354→        })?;
355→
356→    // Load history
357→    let history_path = dirs::home_dir().map(|h| h.join(".spice").join("query_history.txt"));
358→    if let Some(ref path) = history_path {
359→        let _ = rl.load_history(path);
360→    }
361→
362→    let mut tracked_queries: HashMap<String, TrackedQuery> = HashMap::new();
363→
364→    loop {
365→        let input = match read_query_input(&mut rl) {
366→            Ok(Some(input)) => input,
367→            Ok(None) => continue,
368→            Err(ReadlineError::Interrupted | ReadlineError::Eof) => {
369→                println!();
370→                break;
371→            }
372→            Err(e) => {
373→                println!("\x1b[31mError:\x1b[0m {e}");
374→                continue;
375→            }
376→        };
377→
378→        let input = input.trim();
379→        if input.is_empty() {
380→            continue;
381→        }
382→
383→        // Handle special commands
384→        if input.starts_with('.') {
385→            if !handle_special_command(client, input, &mut tracked_queries).await {
386→                break;
387→            }
388→            continue;
389→        }
390→
391→        // Handle regular exit commands
392→        let lower_input = input.to_lowercase();
393→        if matches!(lower_input.as_str(), "exit" | "quit" | "q") {
394→            break;
395→        }
396→
397→        if lower_input == "help" {
398→            print_query_help();
399→            continue;
400→        }
401→
402→        // Add to history
403→        let _ = rl.add_history_entry(input);
404→
405→        // Submit query
406→        let job = match client.query(input).await {
407→            Ok(j) => j,
408→            Err(e) => {
409→                println!("\x1b[31mError:\x1b[0m {e}");
410→                continue;
411→            }
412→        };
413→
414→        let query_id = job.id().to_string();
415→
416→        // Get initial status
417→        let initial_state = match job.status().await {
418→            Ok(s) => s.to_string(),
419→            Err(_) => "PENDING".to_string(),
420→        };
421→
422→        // Track the query
423→        tracked_queries.insert(
424→            query_id.clone(),
425→            TrackedQuery {
426→                query_id: query_id.clone(),
427→                sql: input.to_string(),
428→                status: initial_state.clone(),
429→                submitted_at: Instant::now(),
430→            },
431→        );
432→
433→        println!("Submitted query: {query_id} ({initial_state})");
434→        println!("Press Ctrl+C to stop waiting (query continues in background)");
435→
436→        // Poll for completion
437→        let (final_status, was_cancelled, elapsed) =
438→            poll_for_completion(client, &query_id, None).await;
439→
440→        if was_cancelled {
441→            println!("\nStopped waiting. Check status with: .status {query_id}");
442→            println!("Wait for completion with: .wait {query_id}");
443→            continue;
444→        }
445→
446→        // Update tracked query
447→        if let Some(tracked) = tracked_queries.get_mut(&query_id)
448→            && let Some(ref status) = final_status
449→        {
450→            tracked.status = status.to_string();
451→        }
452→
453→        // Handle final status
454→        if let Some(status) = final_status {
455→            if status.is_success() {
456→                if let Err(e) =
457→                    display_results(client, &query_id, elapsed, OutputFormat::Table).await
458→                {
459→                    println!("\x1b[31mError displaying results:\x1b[0m {e}");
460→                }
461→            } else if status.is_failed() {
462→                println!("\x1b[31m✗ FAILED\x1b[0m");
463→                let job = client.get_query(&query_id).ok();
464→                if let Some(job) = job
465→                    && let Ok(info) = job.info().await
466→                    && let Some(err) = info.error
467→                {
468→                    println!("Error: {}", err.message);
469→                }
470→            } else if status.is_cancelled() {
471→                println!("\x1b[33m⊘ CANCELLED\x1b[0m");
472→            } else {
473→                println!("Query ended with status: {status}");
474→            }
475→        }
476→    }
477→
478→    // Save history
479→    if let Some(ref path) = history_path {
480→        if let Some(parent) = path.parent() {
481→            let _ = std::fs::create_dir_all(parent);
482→        }
483→        let _ = rl.save_history(path);
484→    }
485→
486→    Ok(())
487→}
