489→fn read_query_input(
490→    rl: &mut Editor<(), rustyline::history::DefaultHistory>,
491→) -> rustyline::Result<Option<String>> {
492→    let mut query = String::new();
493→    let mut first_line = true;
494→
495→    loop {
496→        let prompt = if first_line { "query> " } else { "     > " };
497→        let line = rl.readline(prompt)?;
498→
499→        if !query.is_empty() {
500→            query.push('\n');
501→        }
502→        query.push_str(&line);
503→
504→        let trimmed = query.trim();
505→        let lower = trimmed.to_lowercase();
506→
507→        // Check for special commands on first line
508→        if first_line
509→            && (lower == "help"
510→                || lower == "exit"
511→                || lower == "quit"
512→                || lower == "q"
513→                || trimmed.starts_with('.'))
514→        {
515→            break;
516→        }
517→
518→        // Check if query ends with semicolon
519→        if trimmed.ends_with(';') {
520→            break;
521→        }
522→
523→        first_line = false;
524→    }
525→
526→    let result = query.trim().to_string();
527→    if result.is_empty() {
528→        Ok(None)
529→    } else {
530→        Ok(Some(result))
531→    }
532→}
533→
534→async fn handle_special_command(
535→    client: &Arc<Client>,
536→    cmd: &str,
537→    tracked_queries: &mut HashMap<String, TrackedQuery>,
538→) -> bool {
539→    let parts: Vec<&str> = cmd.split_whitespace().collect();
540→    if parts.is_empty() {
541→        return true;
542→    }
543→
544→    let command = parts[0].to_lowercase();
545→    let args = &parts[1..];
546→
547→    match command.as_str() {
548→        ".exit" | ".quit" | ".q" => return false,
549→
550→        ".help" => print_query_help(),
551→
552→        ".list" => {
553→            if tracked_queries.is_empty() {
554→                println!("No tracked queries. Submit a query to start tracking.");
555→                return true;
556→            }
557→
558→            let mut table = TableOutput::new(vec!["QUERY ID", "STATUS", "SUBMITTED", "SQL"]);
559→            for q in tracked_queries.values() {
560→                let ago = format_duration_ago(q.submitted_at.elapsed());
561→                let sql = if q.sql.len() > 37 {
562→                    format!("{}...", &q.sql[..37])
563→                } else {
564→                    q.sql.clone()
565→                };
566→                table.add_row(vec![q.query_id.clone(), q.status.clone(), ago, sql]);
567→            }
568→            table.print();
569→        }
570→
571→        ".status" => {
572→            if args.is_empty() {
573→                println!("Usage: .status <query_id>");
574→                return true;
575→            }
576→            let query_id = resolve_query_id(args[0], tracked_queries);
577→            if query_id.is_empty() {
578→                return true;
579→            }
580→            match client.get_query(&query_id) {
581→                Ok(job) => match job.info().await {
582→                    Ok(info) => display_query_info(&info),
583→                    Err(e) => println!("\x1b[31mError:\x1b[0m {e}"),
584→                },
585→                Err(e) => println!("\x1b[31mError:\x1b[0m {e}"),
586→            }
587→        }
588→
589→        ".results" => {
590→            if args.is_empty() {
591→                println!("Usage: .results <query_id>");
592→                return true;
593→            }
594→            let query_id = resolve_query_id(args[0], tracked_queries);
595→            if query_id.is_empty() {
596→                return true;
597→            }
598→            if let Err(e) =
599→                display_results(client, &query_id, Duration::ZERO, OutputFormat::Table).await
600→            {
601→                println!("\x1b[31mError:\x1b[0m {e}");
602→            }
603→        }
604→
605→        ".wait" => {
606→            if args.is_empty() {
607→                println!("Usage: .wait <query_id>");
608→                return true;
609→            }
610→            let query_id = resolve_query_id(args[0], tracked_queries);
611→            if query_id.is_empty() {
612→                return true;
613→            }
614→            wait_for_query(client, &query_id, tracked_queries).await;
615→        }
616→
617→        ".cancel" => {
618→            if args.is_empty() {
619→                println!("Usage: .cancel <query_id>");
620→                return true;
621→            }
622→            let query_id = resolve_query_id(args[0], tracked_queries);
623→            if query_id.is_empty() {
624→                return true;
625→            }
626→            match client.cancel_query(&query_id).await {
627→                Ok(info) => {
628→                    println!(
629→                        "Query {} cancelled (status: {})",
630→                        info.query_id, info.status
631→                    );
632→                    if let Some(tracked) = tracked_queries.get_mut(&query_id) {
633→                        tracked.status = info.status.to_string();
634→                    }
635→                }
636→                Err(e) => println!("\x1b[31mError:\x1b[0m {e}"),
637→            }
638→        }
639→
640→        ".clear" => {
641→            if !args.is_empty() && args[0].eq_ignore_ascii_case("history") {
642→                println!("Query history cleared.");
643→            } else {
644→                tracked_queries.clear();
645→                println!("Tracked queries cleared.");
646→            }
647→        }
648→
649→        _ => println!("Unknown command: {command}. Type .help for available commands."),
650→    }
651→
652→    true
653→}
654→
655→fn resolve_query_id(partial: &str, tracked_queries: &HashMap<String, TrackedQuery>) -> String {
656→    // Try exact match
657→    if tracked_queries.contains_key(partial) {
658→        return partial.to_string();
659→    }
660→
661→    // Try partial match
662→    let matches: Vec<&str> = tracked_queries
663→        .keys()
664→        .filter(|id| id.starts_with(partial) || id.contains(partial))
665→        .map(String::as_str)
666→        .collect();
667→
668→    if matches.len() == 1 {
669→        return matches[0].to_string();
670→    } else if matches.len() > 1 {
671→        println!(
672→            "Multiple queries match '{}': {}. Please be more specific.",
673→            partial,
674→            matches.join(", ")
675→        );
676→        return String::new();
677→    }
678→
679→    // No match in tracked queries, use the ID as-is
680→    partial.to_string()
681→}
