683→async fn wait_for_query(
684→    client: &Arc<Client>,
685→    query_id: &str,
686→    tracked_queries: &mut HashMap<String, TrackedQuery>,
687→) {
688→    println!("Press Ctrl+C to stop waiting (query continues in background)");
689→
690→    let (final_status, was_cancelled, elapsed) = poll_for_completion(client, query_id, None).await;
691→
692→    if was_cancelled {
693→        println!("\nStopped waiting. Check status with: .status {query_id}");
694→        return;
695→    }
696→
697→    // Update tracked query
698→    if let Some(tracked) = tracked_queries.get_mut(query_id)
699→        && let Some(ref status) = final_status
700→    {
701→        tracked.status = status.to_string();
702→    }
703→
704→    if let Some(status) = final_status {
705→        if status.is_success() {
706→            if let Err(e) = display_results(client, query_id, elapsed, OutputFormat::Table).await {
707→                println!("\x1b[31mError displaying results:\x1b[0m {e}");
708→            }
709→        } else if status.is_failed() {
710→            println!("\x1b[31m✗ FAILED\x1b[0m");
711→            let job = client.get_query(query_id).ok();
712→            if let Some(job) = job
713→                && let Ok(info) = job.info().await
714→                && let Some(err) = info.error
715→            {
716→                println!("Error: {}", err.message);
717→            }
718→        } else if status.is_cancelled() {
719→            println!("\x1b[33m⊘ CANCELLED\x1b[0m");
720→        }
721→    }
722→}
723→
724→async fn poll_for_completion(
725→    client: &Arc<Client>,
726→    query_id: &str,
727→    timeout: Option<Duration>,
728→) -> (Option<QueryStatus>, bool, Duration) {
729→    let start_time = Instant::now();
730→    let mut spinner_idx = 0;
731→    let mut interval = tokio::time::interval(POLL_INTERVAL);
732→
733→    // Set up Ctrl+C handler
734→    let (cancel_tx, mut cancel_rx) = mpsc::channel::<()>(1);
735→    let _guard = CtrlCGuard::new(cancel_tx);
736→
737→    loop {
738→        select! {
739→            _ = cancel_rx.recv() => {
740→                // Clear spinner line
741→                print!("\r\x1b[K");
742→                let _ = std::io::stdout().flush();
743→                return (None, true, start_time.elapsed());
744→            }
745→            _ = interval.tick() => {
746→                // Check timeout
747→                if let Some(t) = timeout
748→                    && start_time.elapsed() > t
749→                {
750→                    print!("\r\x1b[K");
751→                    let _ = std::io::stdout().flush();
752→                    println!("Timeout exceeded");
753→                    return (None, true, start_time.elapsed());
754→                }
755→
756→                if let Ok(job) = client.get_query(query_id)
757→                    && let Ok(status) = job.status().await {
758→                        let elapsed = start_time.elapsed();
759→
760→                        if status.is_terminal() {
761→                            // Clear spinner and show final status
762→                            print!("\r\x1b[K");
763→                            let _ = std::io::stdout().flush();
764→                            if status.is_success() {
765→                                println!("\x1b[32m✓ SUCCEEDED\x1b[0m ({:.1}s)", elapsed.as_secs_f64());
766→                            }
767→                            return (Some(status), false, elapsed);
768→                        }
769→
770→                        // Update spinner
771→                        let frame = SPINNER_FRAMES[spinner_idx % SPINNER_FRAMES.len()];
772→                        spinner_idx += 1;
773→                        print!("\r{} {} ({:.1}s)...", frame, status, elapsed.as_secs_f64());
774→                        let _ = std::io::stdout().flush();
775→                    }
776→                // Continue polling on transient errors
777→            }
778→        }
779→    }
780→}
781→
782→/// Guard that sends a signal when Ctrl+C is pressed.
783→struct CtrlCGuard {
784→    _handle: Option<tokio::task::JoinHandle<()>>,
785→}
786→
787→impl CtrlCGuard {
788→    fn new(tx: mpsc::Sender<()>) -> Self {
789→        let handle = tokio::spawn(async move {
790→            let _ = tokio::signal::ctrl_c().await;
791→            let _ = tx.send(()).await;
792→        });
793→        Self {
794→            _handle: Some(handle),
795→        }
796→    }
797→}
798→
799→async fn display_results(
800→    client: &Arc<Client>,
801→    query_id: &str,
802→    elapsed: Duration,
803→    output: OutputFormat,
804→) -> Result<()> {
805→    // First get query info to check status
806→    let job = client
807→        .get_query(query_id)
808→        .map_err(|e| crate::error::Error::InvalidResponse {
809→            message: e.to_string(),
810→        })?;
811→
812→    let info = job
813→        .info()
814→        .await
815→        .map_err(|e| crate::error::Error::InvalidResponse {
816→            message: e.to_string(),
817→        })?;
818→
819→    if !info.status.is_success() {
820→        return Err(crate::error::Error::InvalidResponse {
821→            message: format!(
822→                "query '{}' is still {}. Use .wait {} to wait for completion",
823→                query_id, info.status, query_id
824→            ),
825→        });
826→    }
827→
828→    // Fetch results as Arrow RecordBatches
829→    let batches = job
830→        .results()
831→        .await
832→        .map_err(|e| crate::error::Error::InvalidResponse {
833→            message: format!("getting results: {e}"),
834→        })?;
835→
836→    let total_rows: usize = batches
837→        .iter()
838→        .map(arrow::array::RecordBatch::num_rows)
839→        .sum();
840→
841→    if total_rows == 0 {
842→        if elapsed > Duration::ZERO {
843→            println!("Time: {:.8} seconds. 0 rows.", elapsed.as_secs_f64());
844→        } else {
845→            println!("No results.");
846→        }
847→        return Ok(());
848→    }
849→
850→    if output == OutputFormat::Json {
851→        let mut buf = Vec::new();
852→        {
853→            let mut writer = arrow_json::ArrayWriter::new(&mut buf);
854→            writer
855→                .write_batches(&batches.iter().collect::<Vec<_>>())
856→                .map_err(|e| crate::error::Error::InvalidResponse {
857→                    message: format!("serializing results to JSON: {e}"),
858→                })?;
859→            writer
860→                .finish()
861→                .map_err(|e| crate::error::Error::InvalidResponse {
862→                    message: format!("finalizing JSON output: {e}"),
863→                })?;
864→        }
865→        let json = String::from_utf8(buf).map_err(|e| crate::error::Error::InvalidResponse {
866→            message: format!("encoding JSON as UTF-8: {e}"),
867→        })?;
868→        println!("{json}");
869→        return Ok(());
870→    }
871→
872→    // Use pretty formatting with types to display results
873→    let formatted =
874→        format_batches_with_types(&batches).map_err(|e| crate::error::Error::InvalidResponse {
875→            message: format!("formatting results: {e}"),
876→        })?;
877→
878→    println!("{formatted}");
879→
880→    // Show timing and row count
881→    if elapsed > Duration::ZERO {
882→        println!(
883→            "\nTime: {:.8} seconds. {} rows.",
884→            elapsed.as_secs_f64(),
885→            total_rows
886→        );
887→    } else {
888→        println!("\n{total_rows} row(s)");
889→    }
890→
891→    Ok(())
892→}
