906→fn format_duration_ago(duration: Duration) -> String {
907→    let secs = duration.as_secs();
908→    if secs < 60 {
909→        format!("{secs}s ago")
910→    } else if secs < 3600 {
911→        format!("{}m ago", secs / 60)
912→    } else {
913→        format!("{}h ago", secs / 3600)
914→    }
