 17→//! Add command - adds a Spicepod to the project.
 18→
 19→use crate::context::RuntimeContext;
 20→use crate::error::{ConfigIoSnafu, Result};
 21→use crate::registry;
 22→use clap::Args;
 23→use snafu::ResultExt;
 24→use spicepod::spec::SpicepodDefinition;
 25→use std::path::Path;
 26→
 27→/// Arguments for the add command.
 28→#[derive(Args, Debug)]
 29→pub struct AddArgs {
 30→    /// Spicepod path (e.g., spiceai/quickstart, ./local/path, or spiceai/quickstart@v1.0)
 31→    pub pod_path: String,
 32→}
 33→
 34→/// Execute the add command.
 35→///
 36→/// # Errors
 37→///
 38→/// Returns an error if the Spicepod cannot be fetched or added.
 39→pub async fn execute(ctx: &RuntimeContext, args: AddArgs) -> Result<()> {
 40→    execute_add_or_connect(ctx, args, false).await
 41→}
 42→
 43→/// Execute the add or connect command with optional cloud authentication.
 44→///
 45→/// # Errors
 46→///
 47→/// Returns an error if the Spicepod cannot be fetched or added.
 48→pub async fn execute_add_or_connect(
 49→    ctx: &RuntimeContext,
 50→    args: AddArgs,
 51→    connect: bool,
 52→) -> Result<()> {
 53→    let pod_path = &args.pod_path;
 54→
 55→    println!("Getting Spicepod {pod_path} ...");
 56→
 57→    // Build headers
 58→    let mut headers = ctx.get_headers();
 59→
 60→    if connect {
 61→        let api_key = ctx.api_key().ok_or_else(|| {
 62→            crate::error::Error::InvalidArgument {
 63→                message: "Missing or invalid Spice.ai Cloud API key. Run `spice login` to authenticate and continue.".to_string(),
 64→            }
 65→        })?;
 66→
 67→        headers.insert("Spice-Target-Source".to_string(), "spice.ai".to_string());
 68→        headers.insert("X-API-Key".to_string(), api_key.to_string());
 69→    }
 70→
 71→    // Fetch the Spicepod
 72→    let download_path = registry::get_pod(pod_path, ctx.pods_dir(), &headers, ctx.http_client())
 73→        .await
 74→        .map_err(|e| crate::error::Error::InvalidArgument {
 75→            message: e.to_string(),
 76→        })?;
 77→
 78→    // Get relative path for display
 79→    let relative_path = get_relative_path(ctx.app_dir(), &download_path);
 80→
 81→    // Read or create spicepod.yaml
 82→    let spicepod_path = ctx.app_dir().join("spicepod.yaml");
 83→    let mut spicepod: SpicepodDefinition = if spicepod_path.exists() {
 84→        let contents = std::fs::read_to_string(&spicepod_path).context(ConfigIoSnafu {
 85→            operation: "read",
 86→            path: spicepod_path.clone(),
 87→        })?;
 88→        yaml::from_str(&contents).map_err(|e| crate::error::Error::ConfigParse {
 89→            message: e.to_string(),
 90→        })?
 91→    } else {
 92→        // Create a new spicepod.yaml
 93→        let name = ctx
 94→            .app_dir()
 95→            .file_name()
 96→            .and_then(|n| n.to_str())
 97→            .unwrap_or("app");
 98→        println!("\x1b[32mspicepod.yaml initialized!\x1b[0m");
 99→        SpicepodDefinition::new(name)
100→    };
101→
102→    // Add dependency if not already present
103→    if !spicepod.dependencies.contains(&pod_path.clone()) {
104→        spicepod.dependencies.push(pod_path.clone());
105→
106→        // Write updated spicepod.yaml
107→        let yaml = yaml::to_string(&spicepod).map_err(|e| crate::error::Error::ConfigParse {
108→            message: format!("Failed to serialize spicepod.yaml: {e}"),
109→        })?;
110→        std::fs::write(&spicepod_path, yaml).context(ConfigIoSnafu {
111→            operation: "write",
112→            path: spicepod_path,
113→        })?;
114→    }
115→
116→    println!("added {relative_path}");
117→
118→    Ok(())
119→}
120→
121→/// Get a relative path from a base directory.
122→fn get_relative_path(base: &Path, path: &Path) -> String {
123→    path.strip_prefix(base)
124→        .map_or_else(|_| path.display().to_string(), |p| p.display().to_string())
125→}
