 17→//! `spice chat` command - Chat with an LLM.
 18→
 19→use crate::context::RuntimeContext;
 20→use crate::error::{
 21→    ConnectionFailedSnafu, InvalidResponseSnafu, ModelNotFoundSnafu, NoModelsConfiguredSnafu,
 22→    Result,
 23→};
 24→use clap::Args;
 25→use futures::StreamExt;
 26→use repl::util::{Spinner, create_editor_with_history, save_history};
 27→use serde::{Deserialize, Serialize};
 28→use snafu::ResultExt;
 29→use std::io::{self, Read, Write};
 30→use std::time::Instant;
 31→
 32→/// Arguments for the `chat` command.
 33→#[derive(Args, Debug)]
 34→pub struct ChatArgs {
 35→    /// Model to use for chat
 36→    #[arg(long, short)]
 37→    pub model: Option<String>,
 38→
 39→    /// Single message to send (non-interactive mode)
 40→    pub message: Option<String>,
 41→
 42→    /// Temperature for sampling (0.0 = deterministic, higher = more random)
 43→    #[arg(long)]
 44→    pub temperature: Option<f32>,
 45→
 46→    /// Remote Spice instance HTTP endpoint (e.g., `http://localhost:8090`)
 47→    #[arg(long)]
 48→    pub endpoint: Option<String>,
 49→
 50→    /// Custom HTTP headers in format 'Key:Value' (can be specified multiple times)
 51→    #[arg(long = "headers", value_name = "KEY:VALUE")]
 52→    pub custom_headers: Vec<String>,
 53→}
 54→
 55→/// Configuration for chat operations.
 56→struct ChatConfig<'a> {
 57→    model: &'a str,
 58→    temperature: Option<f32>,
 59→    endpoint: Option<&'a str>,
 60→    custom_headers: &'a [String],
 61→}
 62→
 63→/// A chat message.
 64→#[derive(Serialize, Deserialize, Clone)]
 65→struct Message {
 66→    role: String,
 67→    content: String,
 68→}
 69→
 70→/// Request body for chat completions.
 71→#[derive(Serialize)]
 72→struct ChatRequest {
 73→    messages: Vec<Message>,
 74→    model: String,
 75→    stream: bool,
 76→    #[serde(skip_serializing_if = "Option::is_none")]
 77→    temperature: Option<f32>,
 78→    #[serde(skip_serializing_if = "Option::is_none")]
 79→    stream_options: Option<StreamOptions>,
 80→}
 81→
 82→/// Stream options for chat completions.
 83→#[derive(Serialize)]
 84→struct StreamOptions {
 85→    include_usage: bool,
 86→}
 87→
 88→/// A streaming chunk from the chat completions API.
 89→#[derive(Deserialize)]
 90→struct ChatChunk {
 91→    choices: Vec<ChunkChoice>,
 92→    #[serde(default)]
 93→    usage: Option<Usage>,
 94→}
 95→
 96→/// A choice in a chat chunk.
 97→#[derive(Deserialize)]
 98→struct ChunkChoice {
 99→    delta: Delta,
100→}
101→
102→/// Delta content in a streaming response.
103→#[derive(Deserialize)]
104→struct Delta {
105→    #[serde(default)]
106→    content: Option<String>,
107→}
108→
109→/// Token usage statistics.
110→#[derive(Deserialize, Default, Clone)]
111→#[expect(clippy::struct_field_names)]
112→struct Usage {
113→    prompt_tokens: u32,
114→    completion_tokens: u32,
115→    #[expect(dead_code)]
116→    total_tokens: u32,
117→}
118→
119→/// Chat response with timing and usage statistics.
120→struct ChatResponse {
121→    content: String,
122→    total_duration: std::time::Duration,
123→    first_token_duration: Option<std::time::Duration>,
124→    usage: Option<Usage>,
125→}
126→
127→impl ChatResponse {
128→    /// Format the stats output like the Go CLI:
129→    /// `Time: 3.36s (first token 0.45s). Tokens: 1652. Prompt: 1475. Completion: 177 (292.25/s).`
130→    fn format_stats(&self) -> String {
131→        let total_secs = self.total_duration.as_secs_f64();
132→
133→        let first_token_part = self.first_token_duration.map_or(String::new(), |d| {
134→            format!(" (first token {:.2}s)", d.as_secs_f64())
135→        });
136→
137→        if let Some(usage) = &self.usage {
138→            let total_tokens = usage.prompt_tokens + usage.completion_tokens;
139→            let completion_rate = if total_secs > 0.0 {
140→                let rate = f64::from(usage.completion_tokens) / total_secs;
141→                format!(" ({rate:.2}/s)")
142→            } else {
143→                String::new()
144→            };
145→            format!(
146→                "Time: {total_secs:.2}s{first_token_part}. Tokens: {total_tokens}. Prompt: {}. Completion: {}{completion_rate}.",
147→                usage.prompt_tokens, usage.completion_tokens
148→            )
149→        } else {
150→            format!("Time: {total_secs:.2}s{first_token_part}.")
151→        }
152→    }
153→}
154→
155→/// Get or validate a model using the runtime context.
156→async fn get_or_select_model(
157→    ctx: &RuntimeContext,
158→    model: Option<&str>,
159→    endpoint: Option<&str>,
160→    custom_headers: &[String],
161→) -> Result<String> {
162→    let base_endpoint = endpoint.unwrap_or_else(|| ctx.http_endpoint());
163→    let mut headers: Vec<(String, String)> = ctx.get_headers().into_iter().collect();
164→
165→    // Add custom headers from command line
166→    for header in custom_headers {
167→        if let Some((key, value)) = header.split_once(':') {
168→            headers.push((key.trim().to_string(), value.trim().to_string()));
169→        }
170→    }
171→
172→    repl::util::get_or_select_model(ctx.http_client(), base_endpoint, &headers, model)
173→        .await
174→        .map_err(|e| match e {
175→            repl::util::UtilError::ModelNotFound { model, available } => {
176→                ModelNotFoundSnafu { model, available }.build()
177→            }
178→            repl::util::UtilError::NoModelsConfigured => NoModelsConfiguredSnafu.build(),
179→            repl::util::UtilError::ConnectionFailed { endpoint, source } => InvalidResponseSnafu {
180→                message: format!("Failed to connect to {endpoint}: {source}"),
181→            }
182→            .build(),
183→            repl::util::UtilError::InvalidResponse { message } => {
184→                InvalidResponseSnafu { message }.build()
185→            }
186→        })
187→}
188→
189→/// Execute the `chat` command.
190→///
191→/// # Errors
192→///
193→/// Returns an error if the API requests fail or input/output fails.
194→pub async fn execute(ctx: &RuntimeContext, args: &ChatArgs) -> Result<()> {
195→    // Get or select the model
196→    let model = get_or_select_model(
197→        ctx,
198→        args.model.as_deref(),
199→        args.endpoint.as_deref(),
200→        &args.custom_headers,
201→    )
202→    .await?;
203→
204→    // Check if running in a terminal (interactive) vs piped input
205→    let is_terminal = std::io::IsTerminal::is_terminal(&std::io::stdin());
206→
207→    // Read piped stdin if available
208→    let stdin_input = if is_terminal {
209→        None
210→    } else {
211→        let mut input = String::new();
212→        std::io::stdin().read_to_string(&mut input).ok();
213→        let trimmed = input.trim();
214→        if trimmed.is_empty() {
215→            None
216→        } else {
217→            Some(trimmed.to_string())
218→        }
219→    };
220→
221→    // Combine piped input with command line message
222→    let message = match (&args.message, stdin_input) {
223→        (Some(arg_msg), Some(stdin_msg)) => Some(format!("{stdin_msg}\n{arg_msg}")),
224→        (Some(arg_msg), None) => Some(arg_msg.clone()),
225→        (None, Some(stdin_msg)) => Some(stdin_msg),
226→        (None, None) => None,
227→    };
228→
229→    // Create chat config
230→    let config = ChatConfig {
231→        model: &model,
232→        temperature: args.temperature,
233→        endpoint: args.endpoint.as_deref(),
234→        custom_headers: &args.custom_headers,
235→    };
236→
237→    // If a message was provided (command line or piped), send it and exit
238→    if let Some(message) = message {
239→        let messages = vec![Message {
240→            role: "user".to_string(),
241→            content: message,
242→        }];
243→        let response = send_chat_streaming(ctx, &config, &messages, false).await?;
244→        // Only show stats if running in a terminal
245→        if is_terminal {
246→            println!("\n\n{}\n", response.format_stats());
247→        } else {
248→            println!();
249→        }
250→        return Ok(());
251→    }
252→
253→    // Interactive mode
254→    println!("Welcome to the Spice.ai Chat REPL!");
255→    println!("\nUsing model:\n {model}");
256→    println!("\nType your message and press Enter. Type 'exit' to quit.\n");
257→
258→    run_repl(ctx, &config).await
259→}
260→
261→/// Run the REPL loop.
262→async fn run_repl(ctx: &RuntimeContext, config: &ChatConfig<'_>) -> Result<()> {
263→    let (mut rl, history_path) = create_editor_with_history("chat_history.txt").map_err(|e| {
264→        InvalidResponseSnafu {
265→            message: e.to_string(),
266→        }
267→        .build()
268→    })?;
269→
270→    let mut messages: Vec<Message> = Vec::new();
271→
272→    loop {
273→        let readline = rl.readline("chat> ");
274→        let user_input = match readline {
275→            Ok(line) => line,
276→            Err(
277→                rustyline::error::ReadlineError::Interrupted | rustyline::error::ReadlineError::Eof,
278→            ) => {
279→                break;
280→            }
281→            Err(e) => {
282→                eprintln!("Error reading input: {e}");
283→                continue;
284→            }
285→        };
286→
287→        let user_input = user_input.trim();
288→        if user_input.is_empty() {
289→            continue;
290→        }
291→
292→        // Add to history
293→        let _ = rl.add_history_entry(user_input);
294→
295→        // Handle exit commands
296→        if user_input == "exit"
297→            || user_input == "quit"
298→            || user_input == ".exit"
299→            || user_input == ".quit"
300→        {
301→            break;
302→        }
303→
304→        // Handle clear screen
305→        if user_input.to_lowercase() == ".clear" {
306→            print!("\x1b[H\x1b[2J");
307→            let _ = io::stdout().flush();
308→            continue;
309→        }
310→
311→        // Handle clear history (both in-memory and persistent)
312→        if user_input.to_lowercase() == ".clear history" {
313→            messages.clear();
314→            let _ = rl.clear_history();
315→            // Clear persistent history file
316→            if let Some(path) = &history_path {
317→                if std::fs::remove_file(path).is_ok() {
318→                    println!("Chat history cleared.");
319→                } else {
320→                    println!("Chat history cleared (in-memory only).");
321→                }
322→            } else {
323→                println!("Chat history cleared.");
324→            }
325→            continue;
326→        }
327→
328→        // Add user message
329→        messages.push(Message {
330→            role: "user".to_string(),
331→            content: user_input.to_string(),
332→        });
333→
334→        // Send and stream response
335→        match send_chat_streaming(ctx, config, &messages, true).await {
336→            Ok(response) => {
337→                // Print stats first before consuming content
338→                println!("\n\n{}\n", response.format_stats());
339→                // Add assistant response to history
340→                if !response.content.is_empty() {
341→                    messages.push(Message {
342→                        role: "assistant".to_string(),
343→                        content: response.content,
344→                    });
345→                }
346→            }
347→            Err(e) => {
348→                eprintln!("\x1b[31mError\x1b[0m {e}");
349→                // Remove the failed user message
350→                messages.pop();
351→            }
352→        }
353→    }
354→
355→    // Save history
356→    save_history(&mut rl, history_path.as_ref());
357→
358→    Ok(())
359→}
360→
361→/// Send a chat request with streaming response.
362→async fn send_chat_streaming(
363→    ctx: &RuntimeContext,
364→    config: &ChatConfig<'_>,
365→    messages: &[Message],
366→    interactive: bool,
367→) -> Result<ChatResponse> {
368→    let start_time = Instant::now();
369→    let base_endpoint = config.endpoint.unwrap_or_else(|| ctx.http_endpoint());
370→    let url = format!("{base_endpoint}/v1/chat/completions");
371→
372→    let body = ChatRequest {
373→        messages: messages.to_vec(),
374→        model: config.model.to_string(),
375→        stream: true,
376→        temperature: config.temperature,
377→        stream_options: Some(StreamOptions {
378→            include_usage: true,
379→        }),
380→    };
381→
382→    let mut request = ctx
383→        .http_client()
384→        .post(&url)
385→        .header("Content-Type", "application/json")
386→        .header("Accept", "text/event-stream")
387→        .json(&body);
388→
389→    for (key, value) in ctx.get_headers() {
390→        request = request.header(&key, &value);
391→    }
392→
393→    // Add custom headers from command line
394→    for header in config.custom_headers {
395→        if let Some((key, value)) = header.split_once(':') {
396→            request = request.header(key.trim(), value.trim());
397→        }
398→    }
399→
400→    // Start spinner in interactive mode
401→    let spinner = if interactive {
402→        Some(Spinner::start())
403→    } else {
404→        None
405→    };
406→
407→    let response = request
408→        .send()
409→        .await
410→        .context(ConnectionFailedSnafu { endpoint: &url })?;
411→
412→    if !response.status().is_success() {
413→        // Stop spinner on error
414→        if let Some(s) = spinner {
415→            s.stop().await;
416→        }
417→        let status = response.status();
418→        let text = response.text().await.unwrap_or_default();
419→        return Err(InvalidResponseSnafu {
420→            message: format!("Chat request failed: {status} - {text}"),
421→        }
422→        .build());
423→    }
424→
425→    // Stream the response
426→    let mut full_response = String::new();
427→    let mut stream = response.bytes_stream();
428→    let mut spinner = spinner;
429→    let mut first_token_time: Option<std::time::Duration> = None;
430→    let mut usage: Option<Usage> = None;
431→
432→    while let Some(chunk_result) = stream.next().await {
433→        let chunk = chunk_result.map_err(|e| {
434→            InvalidResponseSnafu {
435→                message: format!("Failed to read stream: {e}"),
436→            }
437→            .build()
438→        })?;
439→
440→        let text = String::from_utf8_lossy(&chunk);
441→
442→        // Parse SSE events
443→        for line in text.lines() {
444→            if let Some(data) = line.strip_prefix("data: ") {
445→                if data == "[DONE]" {
446→                    continue;
447→                }
448→
449→                // Parse the JSON chunk
450→                if let Ok(chat_chunk) = serde_json::from_str::<ChatChunk>(data) {
451→                    // Capture usage from the final chunk (if present)
452→                    if chat_chunk.usage.is_some() {
453→                        usage = chat_chunk.usage;
454→                    }
455→
456→                    for choice in &chat_chunk.choices {
457→                        if let Some(content) = &choice.delta.content {
458→                            // Record first token time and stop spinner
459→                            if first_token_time.is_none() {
460→                                first_token_time = Some(start_time.elapsed());
461→                                if let Some(s) = spinner.take() {
462→                                    s.stop().await;
463→                                }
464→                            }
465→                            print!("{content}");
466→                            let _ = io::stdout().flush();
467→                            full_response.push_str(content);
468→                        }
469→                    }
470→                }
471→            }
472→        }
473→    }
474→
475→    // Ensure spinner is stopped
476→    if let Some(s) = spinner {
477→        s.stop().await;
478→    }
479→
480→    let total_duration = start_time.elapsed();
481→
482→    Ok(ChatResponse {
483→        content: full_response,
484→        total_duration,
485→        first_token_duration: first_token_time,
486→        usage,
487→    })
488→}
