 17→//! `spice cluster` command - Cluster operations for Spice runtime.
 18→
 19→use crate::error::{
 20→    ConfigIoSnafu, CreateDirectorySnafu, HomeDirectoryNotFoundSnafu, InvalidArgumentSnafu, Result,
 21→};
 22→use ansi_colors::Color;
 23→use clap::{Args, Subcommand};
 24→use rcgen::{
 25→    BasicConstraints, CertificateParams, DnType, ExtendedKeyUsagePurpose, IsCa, Issuer, KeyPair,
 26→    KeyUsagePurpose, SanType,
 27→};
 28→use snafu::{ResultExt, ensure};
 29→use std::fs;
 30→use std::io::{self, Write};
 31→use std::net::IpAddr;
 32→use std::path::PathBuf;
 33→use std::process::Command;
 34→use time::{Duration, OffsetDateTime};
 35→
 36→const CA_VALIDITY_YEARS: i64 = 10;
 37→const CLIENT_VALIDITY_YEARS: i64 = 1;
 38→const CA_CERT_FILENAME: &str = "ca.crt";
 39→const CA_KEY_FILENAME: &str = "ca.key";
 40→const PKI_DIR_NAME: &str = "pki";
 41→const DOT_SPICE: &str = ".spice";
 42→const CA_CN: &str = "Spice.ai CLI Root CA - DO NOT USE IN PRODUCTION";
 43→const DEFAULT_OU: &str = "unknown";
 44→
 45→/// Arguments for the `cluster` command.
 46→#[derive(Args, Debug)]
 47→pub struct ClusterArgs {
 48→    #[command(subcommand)]
 49→    pub command: ClusterCommands,
 50→}
 51→
 52→/// Cluster subcommands.
 53→#[derive(Subcommand, Debug)]
 54→pub enum ClusterCommands {
 55→    /// TLS certificate operations for clustered mode
 56→    Tls(TlsArgs),
 57→}
 58→
 59→/// TLS subcommand arguments.
 60→#[derive(Args, Debug)]
 61→pub struct TlsArgs {
 62→    #[command(subcommand)]
 63→    pub command: TlsCommands,
 64→}
 65→
 66→/// TLS subcommands.
 67→#[derive(Subcommand, Debug)]
 68→pub enum TlsCommands {
 69→    /// Initialize a test PKI infrastructure for clustered mode
 70→    #[command(
 71→        long_about = "Initialize a test PKI infrastructure by generating a new Certificate Authority (CA).\n\n\
 72→        This command creates:\n\
 73→        - A CA certificate (~/.spice/pki/ca.crt)\n\
 74→        - A CA private key (~/.spice/pki/ca.key)\n\n\
 75→        The CA certificate is valid for 10 years and uses ECDSA P-256.\n\n\
 76→        WARNING: This CA is for development and testing purposes only.\n\
 77→                 DO NOT use these certificates in production environments."
 78→    )]
 79→    Init,
 80→
 81→    /// Create a new client certificate signed by the CA
 82→    #[command(
 83→        long_about = "Create a new client certificate and private key signed by the CA.\n\n\
 84→        This command creates:\n\
 85→        - A client certificate (~/.spice/pki/<client-name>.crt)\n\
 86→        - A client private key (~/.spice/pki/<client-name>.key)\n\n\
 87→        The client certificate is valid for 1 year and uses ECDSA P-256.\n\
 88→        The certificate includes localhost and 127.0.0.1 as Subject Alternative Names (SANs).\n\n\
 89→        The CA must be initialized first using 'spice cluster tls init'."
 90→    )]
 91→    Add {
 92→        /// Name of the client/node
 93→        client_name: String,
 94→
 95→        /// Additional host to include in Subject Alternative Names
 96→        #[arg(long)]
 97→        host: Option<String>,
 98→    },
 99→}
100→
101→/// Execute the `cluster` command.
102→///
103→/// # Errors
104→///
105→/// Returns an error if certificate generation or file I/O fails.
106→pub fn execute(args: &ClusterArgs) -> Result<()> {
107→    match &args.command {
108→        ClusterCommands::Tls(tls_args) => match &tls_args.command {
109→            TlsCommands::Init => execute_tls_init(),
110→            TlsCommands::Add { client_name, host } => execute_tls_add(client_name, host.as_deref()),
111→        },
112→    }
113→}
114→
115→/// Get the PKI directory (~/.spice/pki).
116→fn get_pki_dir() -> Result<PathBuf> {
117→    let home_dir = dirs::home_dir().ok_or_else(|| HomeDirectoryNotFoundSnafu.build())?;
118→    Ok(home_dir.join(DOT_SPICE).join(PKI_DIR_NAME))
119→}
120→
121→/// Get the organizational unit from git config email, or default.
122→fn get_organizational_unit() -> String {
123→    Command::new("git")
124→        .args(["config", "--get", "user.email"])
125→        .output()
126→        .ok()
127→        .and_then(|output| {
128→            if output.status.success() {
129→                String::from_utf8(output.stdout)
130→                    .ok()
131→                    .map(|s| s.trim().to_string())
132→                    .filter(|s| !s.is_empty())
133→            } else {
134→                None
135→            }
136→        })
137→        .unwrap_or_else(|| DEFAULT_OU.to_string())
138→}
139→
140→/// Prompt user for confirmation.
141→fn confirm_overwrite(what: &str) -> bool {
142→    print!("{what} already exists. Overwrite (y/n)? ");
143→    let _ = io::stdout().flush();
144→
145→    let mut input = String::new();
146→    if io::stdin().read_line(&mut input).is_ok() {
147→        input.trim().eq_ignore_ascii_case("y")
148→    } else {
149→        false
150→    }
151→}
152→
153→/// Validate client name (alphanumeric, hyphens, underscores).
154→fn validate_client_name(name: &str) -> Result<()> {
155→    ensure!(
156→        !name.is_empty(),
157→        InvalidArgumentSnafu {
158→            message: "client name cannot be empty"
159→        }
160→    );
161→
162→    ensure!(
163→        name.chars()
164→            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'),
165→        InvalidArgumentSnafu {
166→            message: "client name can only contain letters, numbers, hyphens, and underscores"
167→        }
168→    );
169→
170→    Ok(())
171→}
172→
173→/// Initialize the PKI infrastructure with a new CA.
174→fn execute_tls_init() -> Result<()> {
175→    let pki_dir = get_pki_dir()?;
176→    let ca_cert_path = pki_dir.join(CA_CERT_FILENAME);
177→    let ca_key_path = pki_dir.join(CA_KEY_FILENAME);
178→
179→    // Check if CA already exists
180→    if ca_cert_path.exists() && !confirm_overwrite("CA certificate") {
181→        println!("Aborted.");
182→        return Ok(());
183→    }
184→
185→    // Create PKI directory
186→    fs::create_dir_all(&pki_dir).context(CreateDirectorySnafu {
187→        path: pki_dir.clone(),
188→    })?;
189→
190→    // Set secure permissions on PKI directory
191→    #[cfg(unix)]
192→    {
193→        use std::os::unix::fs::PermissionsExt;
194→        let permissions = fs::Permissions::from_mode(0o700);
195→        fs::set_permissions(&pki_dir, permissions)
196→            .context(CreateDirectorySnafu { path: pki_dir })?;
197→    }
198→
199→    let ou = get_organizational_unit();
200→
201→    // Generate CA certificate and key
202→    let not_before = OffsetDateTime::now_utc();
203→    let not_after = not_before + Duration::days(CA_VALIDITY_YEARS * 365);
204→
205→    let mut ca_params = CertificateParams::default();
206→    ca_params.distinguished_name.push(DnType::CommonName, CA_CN);
207→    ca_params
208→        .distinguished_name
209→        .push(DnType::OrganizationalUnitName, &ou);
210→    ca_params.not_before = not_before;
211→    ca_params.not_after = not_after;
212→    ca_params.is_ca = IsCa::Ca(BasicConstraints::Constrained(0));
213→    ca_params.key_usages = vec![
214→        KeyUsagePurpose::DigitalSignature,
215→        KeyUsagePurpose::KeyCertSign,
216→        KeyUsagePurpose::CrlSign,
217→    ];
218→
219→    let ca_key_pair = KeyPair::generate().map_err(|e| crate::error::Error::InvalidArgument {
220→        message: format!("Failed to generate CA key pair: {e}"),
221→    })?;
222→
223→    let ca_cert =
224→        ca_params
225→            .self_signed(&ca_key_pair)
226→            .map_err(|e| crate::error::Error::InvalidArgument {
227→                message: format!("Failed to create CA certificate: {e}"),
228→            })?;
229→
230→    // Write CA certificate
231→    fs::write(&ca_cert_path, ca_cert.pem()).context(ConfigIoSnafu {
232→        operation: "write",
233→        path: ca_cert_path.clone(),
234→    })?;
235→
236→    // Write CA private key
237→    fs::write(&ca_key_path, ca_key_pair.serialize_pem()).context(ConfigIoSnafu {
238→        operation: "write",
239→        path: ca_key_path.clone(),
240→    })?;
241→
242→    // Set secure permissions on files
243→    #[cfg(unix)]
244→    {
245→        use std::os::unix::fs::PermissionsExt;
246→        let permissions = fs::Permissions::from_mode(0o600);
247→        fs::set_permissions(&ca_cert_path, permissions.clone()).context(ConfigIoSnafu {
248→            operation: "set permissions on",
249→            path: ca_cert_path.clone(),
250→        })?;
251→        fs::set_permissions(&ca_key_path, permissions).context(ConfigIoSnafu {
252→            operation: "set permissions on",
253→            path: ca_key_path.clone(),
254→        })?;
255→    }
256→
257→    println!();
258→    println!(
259→        "{}",
260→        Color::Green.paint("Test PKI infrastructure initialized successfully!")
261→    );
262→    println!();
263→    println!("CA Certificate: {}", ca_cert_path.display());
264→    println!("CA Private Key: {}", ca_key_path.display());
265→    println!(
266→        "Validity:       {CA_VALIDITY_YEARS} years (until {})",
267→        not_after.date()
268→    );
269→    println!("OU:             {ou}");
270→    println!();
271→    println!(
272→        "{}",
273→        Color::Yellow.paint("WARNING: This CA is for development and testing only.")
274→    );
275→    println!(
276→        "{}",
277→        Color::Yellow.paint("         DO NOT use these certificates in production!")
278→    );
279→    println!();
280→    println!("Next steps:");
281→    println!(
282→        "  Run {} to create a certificate for a cluster member.",
283→        Color::Cyan.paint("spice cluster tls add <client-name>")
284→    );
285→
286→    Ok(())
287→}
288→
289→/// Create a client certificate signed by the CA.
290→fn execute_tls_add(client_name: &str, host: Option<&str>) -> Result<()> {
291→    validate_client_name(client_name)?;
292→
293→    let pki_dir = get_pki_dir()?;
294→    let ca_cert_path = pki_dir.join(CA_CERT_FILENAME);
295→    let ca_key_path = pki_dir.join(CA_KEY_FILENAME);
296→    let client_cert_path = pki_dir.join(format!("{client_name}.crt"));
297→    let client_key_path = pki_dir.join(format!("{client_name}.key"));
298→
299→    // Check if CA exists
300→    ensure!(
301→        ca_cert_path.exists(),
302→        InvalidArgumentSnafu {
303→            message: "CA certificate not found. Run 'spice cluster tls init' first."
304→        }
305→    );
306→    ensure!(
307→        ca_key_path.exists(),
308→        InvalidArgumentSnafu {
309→            message: "CA private key not found. Run 'spice cluster tls init' first."
310→        }
311→    );
312→
313→    // Check if client cert already exists
314→    if client_cert_path.exists() && !confirm_overwrite(&format!("Certificate for '{client_name}'"))
315→    {
316→        println!("Aborted.");
317→        return Ok(());
318→    }
319→
320→    // Load CA certificate and key
321→    let ca_cert_pem = fs::read_to_string(&ca_cert_path).context(ConfigIoSnafu {
322→        operation: "read",
323→        path: ca_cert_path,
324→    })?;
325→    let ca_key_pem = fs::read_to_string(&ca_key_path).context(ConfigIoSnafu {
326→        operation: "read",
327→        path: ca_key_path,
328→    })?;
329→
330→    // Parse the CA key and certificate for signing
331→    let ca_key_pair =
332→        KeyPair::from_pem(&ca_key_pem).map_err(|e| crate::error::Error::InvalidArgument {
333→            message: format!("Failed to parse CA private key: {e}"),
334→        })?;
335→    let ca_issuer = Issuer::from_ca_cert_pem(&ca_cert_pem, ca_key_pair).map_err(|e| {
336→        crate::error::Error::InvalidArgument {
337→            message: format!("Failed to parse CA certificate: {e}"),
338→        }
339→    })?;
340→
341→    // Generate client certificate
342→    let not_before = OffsetDateTime::now_utc();
343→    let not_after = not_before + Duration::days(CLIENT_VALIDITY_YEARS * 365);
344→
345→    // Build SANs - always include localhost and 127.0.0.1
346→    let mut dns_names = vec!["localhost".to_string()];
347→    let mut ip_addresses: Vec<IpAddr> = vec![IpAddr::V4(std::net::Ipv4Addr::LOCALHOST)];
348→
349→    // Add optional host to SANs
350→    if let Some(host) = host {
351→        if let Ok(ip) = host.parse::<IpAddr>() {
352→            ip_addresses.push(ip);
353→        } else {
354→            dns_names.push(host.to_string());
355→        }
356→    }
357→
358→    let mut client_params = CertificateParams::default();
359→    client_params
360→        .distinguished_name
361→        .push(DnType::CommonName, client_name);
362→    client_params.not_before = not_before;
363→    client_params.not_after = not_after;
364→    client_params.is_ca = IsCa::NoCa;
365→    client_params.key_usages = vec![
366→        KeyUsagePurpose::DigitalSignature,
367→        KeyUsagePurpose::KeyEncipherment,
368→    ];
369→    client_params.extended_key_usages = vec![
370→        ExtendedKeyUsagePurpose::ClientAuth,
371→        ExtendedKeyUsagePurpose::ServerAuth,
372→    ];
373→
374→    // Add SANs
375→    for dns in &dns_names {
376→        client_params
377→            .subject_alt_names
378→            .push(SanType::DnsName(dns.clone().try_into().map_err(|e| {
379→                crate::error::Error::InvalidArgument {
380→                    message: format!("Invalid DNS name '{dns}': {e}"),
381→                }
382→            })?));
383→    }
384→    for ip in &ip_addresses {
385→        client_params
386→            .subject_alt_names
387→            .push(SanType::IpAddress(*ip));
388→    }
389→
390→    let client_key_pair =
391→        KeyPair::generate().map_err(|e| crate::error::Error::InvalidArgument {
392→            message: format!("Failed to generate client key pair: {e}"),
393→        })?;
394→
395→    let client_cert = client_params
396→        .signed_by(&client_key_pair, &ca_issuer)
397→        .map_err(|e| crate::error::Error::InvalidArgument {
398→            message: format!("Failed to create client certificate: {e}"),
399→        })?;
400→
401→    // Write client certificate
402→    fs::write(&client_cert_path, client_cert.pem()).context(ConfigIoSnafu {
403→        operation: "write",
404→        path: client_cert_path.clone(),
405→    })?;
406→
407→    // Write client private key
408→    fs::write(&client_key_path, client_key_pair.serialize_pem()).context(ConfigIoSnafu {
409→        operation: "write",
410→        path: client_key_path.clone(),
411→    })?;
412→
413→    // Set secure permissions on files
414→    #[cfg(unix)]
415→    {
416→        use std::os::unix::fs::PermissionsExt;
417→        let permissions = fs::Permissions::from_mode(0o600);
418→        fs::set_permissions(&client_cert_path, permissions.clone()).context(ConfigIoSnafu {
419→            operation: "set permissions on",
420→            path: client_cert_path.clone(),
421→        })?;
422→        fs::set_permissions(&client_key_path, permissions).context(ConfigIoSnafu {
423→            operation: "set permissions on",
424→            path: client_key_path.clone(),
425→        })?;
426→    }
427→
428→    println!();
429→    println!(
430→        "{}",
431→        Color::Green.paint(format!(
432→            "Certificate for '{client_name}' created successfully!"
433→        ))
434→    );
435→    println!();
436→    println!("Certificate: {}", client_cert_path.display());
437→    println!("Private Key: {}", client_key_path.display());
438→    println!(
439→        "Validity:    {CLIENT_VALIDITY_YEARS} year (until {})",
440→        not_after.date()
441→    );
442→    println!("CN:          {client_name}");
443→    println!("DNS SANs:    {}", dns_names.join(", "));
444→    println!(
445→        "IP SANs:     {}",
446→        ip_addresses
447→            .iter()
448→            .map(ToString::to_string)
449→            .collect::<Vec<_>>()
450→            .join(", ")
451→    );
452→
453→    Ok(())
454→}
