323→fn get_base_url() -> String {
324→    if let Ok(url) = std::env::var("SPICE_CLOUD_API_URL") {
325→        return url;
326→    }
327→
328→    // Use dev API for dev versions
329→    let version = crate::commands::version::cli_version();
330→    if version.ends_with("-dev") {
331→        return DEV_CLOUD_API_BASE_URL.to_string();
332→    }
333→
334→    CLOUD_API_BASE_URL.to_string()
