17→use async_trait::async_trait;
18→use keyring::Entry;
19→use secrecy::SecretString;
20→use snafu::Snafu;
21→
22→use crate::SecretStore;
23→
24→const KEYRING_SECRET_PREFIX: &str = "spice_";
25→
26→#[derive(Debug, Snafu)]
27→pub enum Error {
28→    #[snafu(display("Unable to get secret from keyring: {source}"))]
29→    UnableToGetSecret { source: keyring::Error },
30→
31→    #[snafu(display("Unable to get keyring secret value: {source}"))]
32→    UnableToGetSecretValue { source: keyring::Error },
33→}
34→
35→pub struct KeyringSecretStore {}
36→
37→impl Default for KeyringSecretStore {
38→    fn default() -> Self {
39→        Self::new()
40→    }
41→}
42→
43→impl KeyringSecretStore {
44→    #[must_use]
45→    pub fn new() -> Self {
46→        Self {}
47→    }
48→}
49→
50→#[async_trait]
51→impl SecretStore for KeyringSecretStore {
52→    async fn get_secret(&self, key: &str) -> crate::AnyErrorResult<Option<SecretString>> {
53→        // Try with prefixed key first
54→        let prefixed_key = format!("{KEYRING_SECRET_PREFIX}{key}");
55→
56→        // Try prefixed key
57→        match (
58→            Entry::new(&prefixed_key, "spiced"),
59→            Entry::new(key, "spiced"),
60→        ) {
61→            (Ok(prefixed_entry), Ok(fallback_entry)) => {
62→                // Try getting password with prefixed key first
63→                match prefixed_entry.get_password() {
64→                    Ok(secret) => return Ok(Some(SecretString::from(secret))),
65→                    Err(keyring::Error::NoEntry) => {
66→                        // Prefixed key failed, try fallback
67→                        match fallback_entry.get_password() {
68→                            Ok(secret) => Ok(Some(SecretString::from(secret))),
69→                            Err(keyring::Error::NoEntry) => Ok(None),
70→                            Err(err) => {
71→                                Err(Box::new(Error::UnableToGetSecretValue { source: err }))
72→                            }
73→                        }
74→                    }
75→                    Err(err) => Err(Box::new(Error::UnableToGetSecretValue { source: err })),
76→                }
77→            }
78→            (Err(keyring::Error::NoEntry), Ok(fallback_entry)) => {
79→                // Prefixed entry creation failed, try fallback
80→                match fallback_entry.get_password() {
81→                    Ok(secret) => Ok(Some(SecretString::from(secret))),
82→                    Err(keyring::Error::NoEntry) => Ok(None),
83→                    Err(err) => Err(Box::new(Error::UnableToGetSecretValue { source: err })),
84→                }
85→            }
86→            (Err(err), _) if !matches!(err, keyring::Error::NoEntry) => {
87→                Err(Box::new(Error::UnableToGetSecret { source: err }))
88→            }
89→            (_, Err(err)) => Err(Box::new(Error::UnableToGetSecret { source: err })),
90→            _ => Ok(None),
91→        }
92→    }
93→}
