 72→pub struct Secrets {
 73→    // Use an IndexMap to maintain the order of the secret stores.
 74→    // This order is the reverse of the order in which the secret stores are defined in the SpicePod.
 75→    // This maintains the precedence order we want, since we will search through the secret stores in their order here.
 76→    stores: IndexMap<String, Arc<dyn SecretStore>>,
 77→}
 78→
 79→pub struct ParamStr<'a>(pub &'a str);
 80→
 81→impl Secrets {
 82→    #[must_use]
 83→    pub fn new() -> Self {
 84→        Self {
 85→            stores: IndexMap::new(),
 86→        }
 87→    }
 88→
 89→    #[must_use]
 90→    pub fn new_for_cluster_executor(
 91→        expander: Box<dyn crate::stores::scheduler_rpc::ClusterSecretExpander>,
 92→        executor_id: String,
 93→    ) -> Self {
 94→        let mut stores = IndexMap::new();
 95→        stores.insert(
 96→            "scheduler_rpc".to_string(),
 97→            Arc::new(SchedulerRPCSecretStore::new(expander, executor_id)) as Arc<dyn SecretStore>,
 98→        );
 99→
100→        Self { stores }
101→    }
102→
103→    /// Initializes the runtime secrets based on the provided secret store configuration.
104→    ///
105→    /// If no secret stores are provided, the default secret store is set to `env`.
106→    ///
107→    /// # Errors
108→    ///
109→    /// Returns an error when the `from` field references an unknown store or when a store
110→    /// requires (or disallows) a selector and the config is invalid.
111→    pub async fn load_from(&mut self, secrets: &[SpicepodSecret]) -> Result<()> {
112→        self.stores.clear();
113→
114→        for secret in secrets {
115→            let store_type = spicepod_secret_store_type(secret)?;
116→
117→            let secret_store = match load_secret_store(store_type).await {
118→                Ok(secret_store) => secret_store,
119→                Err(e) => {
120→                    tracing::error!("Error loading secret store {}: {e}", secret.name);
121→                    continue;
122→                }
123→            };
124→
125→            self.stores.insert(secret.name.clone(), secret_store);
126→        }
127→
128→        if self.stores.is_empty() {
129→            let default_store = load_default_store();
130→            self.stores.insert("env".to_string(), default_store);
131→        }
132→
133→        // Reverse the order of the secret stores to maintain the expected precedence order.
134→        self.stores.reverse();
135→
136→        Ok(())
137→    }
138→
139→    pub async fn inject_secrets(&self, key: &str, param_str: ParamStr<'_>) -> SecretString {
140→        tracing::trace!("Injecting secrets for: {}", key);
141→        let mut result = String::new();
142→        let mut last_end = 0;
143→        for secret_replacement in SecretReplacementMatcher::new(param_str.0) {
144→            tracing::debug!(
145→                "Found secret replacement: Store name: {}, Key: {}, Span: {:?}",
146→                secret_replacement.store_name,
147→                secret_replacement.key,
148→                secret_replacement.span,
149→            );
150→
151→            // Append text from last match to the start of the current match
152→            result.push_str(&param_str.0[last_end..secret_replacement.span.start]);
153→
154→            // Get the secret value from the store
155→            let secret = self
156→                .get_store_secret(
157→                    &param_str,
158→                    &secret_replacement.store_name,
159→                    &secret_replacement.key,
160→                )
161→                .await
162→                .unwrap_or_default();
163→
164→            // Replace the token with the desired string
165→            result.push_str(&secret);
166→
167→            // Update the last end to the end of the current match
168→            last_end = secret_replacement.span.end;
169→        }
170→
171→        // Append the remaining text after the last match
172→        result.push_str(&param_str.0[last_end..]);
173→
174→        SecretString::from(result)
175→    }
176→
177→    /// Gets a secret key from the connected secret stores in precedence order.
178→    ///
179→    /// # Errors
180→    ///
181→    /// Propagates any error returned by an underlying secret store implementation.
182→    pub async fn get_secret(&self, key: &str) -> AnyErrorResult<Option<SecretString>> {
183→        for store in self.stores.values() {
184→            match store.get_secret(key).await {
185→                Ok(Some(secret)) => return Ok(Some(secret)),
186→                Ok(None) => {}
187→                Err(e) => return Err(e),
188→            }
189→        }
190→
191→        Ok(None)
192→    }
193→
194→    async fn get_store_secret(
195→        &self,
196→        param_str: &ParamStr<'_>,
197→        store_name: &str,
198→        key: &str,
199→    ) -> Option<String> {
200→        // This is a special case for loading secrets across stores in precedence order
201→        if store_name == SECRETS {
202→            match self.get_secret(key).await {
203→                Ok(Some(secret)) => return Some(secret.expose_secret().to_string()),
204→                Ok(None) => {
205→                    tracing::error!("Key '{key}' not found in any connected secrets.");
206→                    return None;
207→                }
208→                Err(e) => {
209→                    tracing::error!("Error getting secret: {}", e);
210→                    return None;
211→                }
212→            }
213→        }
214→
215→        let secret = if let Some(store) = self.stores.get(store_name) {
216→            match store.get_secret(key).await {
217→                Ok(Some(secret)) => secret.expose_secret().to_string(),
218→                Ok(None) => {
219→                    tracing::error!("Key {key} not found in secret store: {store_name}");
220→                    return None;
221→                }
222→                Err(e) => {
223→                    tracing::error!("Error getting secret: {}", e);
224→                    return None;
225→                }
226→            }
227→        } else {
228→            tracing::error!(
229→                "Secret '{store_name}' referenced in {} not found.",
230→                param_str.0
231→            );
232→            return None;
233→        };
234→
235→        Some(secret)
236→    }
237→}
