245→/// Extract all secret references from a string (e.g., spicepod YAML content).
246→///
247→/// Returns a map where keys are secret keys and values are the store names they reference.
248→/// For example, `${ env:MY_VAR }` returns `("MY_VAR", "env")` and
249→/// `${ secrets:API_KEY }` returns `("API_KEY", "secrets")`.
250→///
251→/// # Example
252→/// ```
253→/// use runtime_secrets::extract_secret_references;
254→///
255→/// let yaml = r#"
256→/// params:
257→///   api_key: ${ secrets:OPENAI_KEY }
258→///   user: ${ env:DB_USER }
259→/// "#;
260→///
261→/// let refs = extract_secret_references(yaml);
262→/// assert_eq!(refs.get("OPENAI_KEY"), Some(&"secrets".to_string()));
263→/// assert_eq!(refs.get("DB_USER"), Some(&"env".to_string()));
264→/// ```
265→#[must_use]
266→pub fn extract_secret_references(content: &str) -> std::collections::HashMap<String, String> {
267→    let mut references = std::collections::HashMap::new();
268→
269→    for secret_replacement in SecretReplacementMatcher::new(content) {
270→        references.insert(
271→            secret_replacement.key.clone(),
272→            secret_replacement.store_name.clone(),
273→        );
274→    }
275→
276→    references
277→}
