290→#[expect(clippy::implicit_hasher)]
291→pub async fn get_params_with_secrets(
292→    secrets: Arc<RwLock<Secrets>>,
293→    params: &HashMap<String, String>,
294→) -> HashMap<String, SecretString> {
295→    let secrets = secrets.read().await;
296→
297→    let mut params_with_secrets: HashMap<String, SecretString> = HashMap::new();
298→
299→    // Inject secrets from the user-supplied params.
300→    // This will replace any instances of `${ store:key }` with the actual secret value.
301→    for (k, v) in params {
302→        let secret = secrets.inject_secrets(k, ParamStr(v)).await;
303→        params_with_secrets.insert(k.clone(), secret);
304→    }
305→
306→    params_with_secrets
307→}
308→
309→fn spicepod_secret_store_type(store: &SpicepodSecret) -> Result<SecretStoreType> {
310→    let provider = secret_store_provider(&store.from);
311→    let selector = secret_selector(&store.from);
312→    match provider {
313→        "env" => {
314→            require_no_selector(provider, selector)?;
315→            if let Some(params) = store.params.as_ref() {
316→                let params = params.as_string_map();
317→                if let Some(path) = params.get("file_path") {
318→                    return Ok(SecretStoreType::EnvCustomPath(path.clone()));
319→                }
320→            }
321→            Ok(SecretStoreType::Env)
322→        }
323→        #[cfg(feature = "keyring-secret-store")]
324→        "keyring" => {
325→            require_no_selector(provider, selector)?;
326→            Ok(SecretStoreType::Keyring)
327→        }
328→        "kubernetes" => Ok(SecretStoreType::Kubernetes(require_selector(
329→            provider, selector,
330→        )?)),
331→        #[cfg(feature = "aws-secrets-manager")]
332→        "aws_secrets_manager" => Ok(SecretStoreType::AwsSecretsManager(require_selector(
333→            provider, selector,
334→        )?)),
335→        "scheduler_rpc" => {
336→            require_no_selector(provider, selector)?;
337→            Ok(SecretStoreType::SchedulerRPC)
338→        }
339→        other => UnknownSecretStoreSnafu {
340→            store: other.to_string(),
341→        }
342→        .fail(),
343→    }
344→}
345→
346→fn require_selector(provider: &str, selector: Option<&str>) -> Result<String> {
347→    let Some(selector) = selector else {
348→        return SecretStoreRequiresSecretSelectorSnafu {
349→            store: provider.to_string(),
350→        }
351→        .fail()?;
352→    };
353→
354→    Ok(selector.to_string())
355→}
356→
357→fn require_no_selector(provider: &str, selector: Option<&str>) -> Result<()> {
358→    if selector.is_some() {
359→        SecretStoreInvalidSecretSelectorSnafu {
360→            store: provider.to_string(),
361→        }
362→        .fail()?;
363→    }
364→
365→    Ok(())
366→}
367→
368→/// Returns the secret store provider - the first part of the `from` field before the first `:`.
369→#[must_use]
370→fn secret_store_provider(from: &str) -> &str {
371→    from.split(':').next().unwrap_or(from)
372→}
373→
374→/// Returns the secret selector - the second part of the `from` field after the first `:`.
375→/// This is optional.
376→#[must_use]
377→fn secret_selector(from: &str) -> Option<&str> {
378→    match from.find(':') {
379→        Some(index) => Some(&from[index + 1..]),
380→        None => None,
381→    }
382→}
383→
384→fn load_default_store() -> Arc<dyn SecretStore> {
385→    Arc::new(EnvSecretStoreBuilder::new().build())
386→}
387→
388→/// Loads the secret store from the provided secret store type.
389→///
390→/// # Errors
391→///
392→/// Returns an error if the secrets cannot be loaded.
393→async fn load_secret_store(store_type: SecretStoreType) -> Result<Arc<dyn SecretStore>> {
394→    match store_type {
395→        SecretStoreType::Env => {
396→            let env_secret_store = EnvSecretStoreBuilder::new().build();
397→
398→            Ok(Arc::new(env_secret_store) as Arc<dyn SecretStore>)
399→        }
400→        SecretStoreType::EnvCustomPath(path) => {
401→            let env_secret_store = EnvSecretStoreBuilder::new().with_path(path.into()).build();
402→
403→            Ok(Arc::new(env_secret_store) as Arc<dyn SecretStore>)
404→        }
405→        #[cfg(feature = "keyring-secret-store")]
406→        SecretStoreType::Keyring => {
407→            Ok(Arc::new(stores::keyring::KeyringSecretStore::new()) as Arc<dyn SecretStore>)
408→        }
409→        SecretStoreType::Kubernetes(secret_name) => {
410→            let mut kubernetes_secret_store =
411→                stores::kubernetes::KubernetesSecretStore::new(secret_name.clone());
412→
413→            kubernetes_secret_store
414→                .init()
415→                .await
416→                .context(UnableToLoadSecretsSnafu)?;
417→
418→            Ok(Arc::new(kubernetes_secret_store) as Arc<dyn SecretStore>)
419→        }
420→        #[cfg(feature = "aws-secrets-manager")]
421→        SecretStoreType::AwsSecretsManager(secret_name) => {
422→            let secret_store =
423→                stores::aws_secrets_manager::AwsSecretsManager::new(secret_name.clone());
424→
425→            secret_store
426→                .init()
427→                .await
428→                .map_err(|e| Error::UnableToInitializeAwsSecretsManager {
429→                    source: Box::new(e),
430→                })?;
431→
432→            Ok(Arc::new(secret_store) as Arc<dyn SecretStore>)
433→        },
434→        SecretStoreType::SchedulerRPC => {
435→            Err(Error::UnableToLoadSecrets {
436→                source: "The `scheduler_rpc` is automatically configured for cluster mode, and should not be specified in the Spicepod.".into()
437→            })
438→        }
439→    }
440→}
